                if (typeof entry.mode !== 'string') entry.mode = 'single';
                if (typeof entry.tune !== 'number' || !isFinite(entry.tune)) entry.tune = 0.5;
                if (typeof entry.tuneUnlocked !== 'boolean') entry.tuneUnlocked = false;
