            id: p.id,
            kind: p.kind,
            slotIndex: p.slotIndex,
            split: !!p.split,
            side: p.side || null,
            bodyMount: !!p.bodyMount,
            role: p.role || this.getModuleVisualRole(p.kind, p.id),
