        // on the quiet path when nothing changed.
        let key = '';
        for (let i = 0; i < raw.length; i++) {
            if (!raw[i]) continue;
            key += (key ? ',' : '') + raw[i];
        }
        if (key === this._activeEnemyTypesKey) return;
        this._activeEnemyTypesKey = key;
