/* --- js/ui/event-viewer.js --- */
"use strict";

/**
 * Event Viewer — combat-event archive for discovered summon roles.
 * Open: Explorations → ARCHIVE → EVENTS
 */
var EventViewerUI = class EventViewerUI {
    constructor() {
        this.visible = false;
        this.selectedIndex = 0;
        this.events = [];
        this.overlay = null;
        this._keyHandler = (e) => this.handleKeyDown(e);
    }

    getEventList() {
        const all = (typeof combatEventConfigManager !== 'undefined')
            ? combatEventConfigManager.getList()
            : [];
        const devMode = typeof startScreenManager !== 'undefined' && startScreenManager.devMode;
        if (devMode || typeof profileManager === 'undefined' || !profileManager.hasActiveProfile()) {
            return all.slice();
        }
        const allowed = {};
        (profileManager.getDiscovered('events') || []).forEach((id) => {
            allowed[String(id)] = true;
        });
        return all.filter((ev) => !!allowed[String(ev.id)]);
    }

    show(options) {
        if (options && Object.prototype.hasOwnProperty.call(options, 'onClose')) {
            this.onClose = options.onClose;
        }
        this.events = this.getEventList();
        if (!this.events.length) return;
        const preferId = options && (options.eventId || options.catalogId);
        if (preferId) {
            const idx = this.events.findIndex((e) => e.id === preferId);
            if (idx >= 0) this.selectedIndex = idx;
        }
        this.selectedIndex = Math.max(0, Math.min(this.selectedIndex, this.events.length - 1));
        this.visible = true;
        this.createUI();
        document.addEventListener('keydown', this._keyHandler);
        if (!(options && options.skipPersist) && typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('event-viewer', {
                eventId: this.events[this.selectedIndex].id
            });
        }
    }

    hide() {
        this.visible = false;
        document.removeEventListener('keydown', this._keyHandler);
        if (this.overlay) {
            this.overlay.remove();
            this.overlay = null;
        }
    }

    close() {
        this.hide();
        if (typeof this.onClose === 'function') this.onClose();
    }

    persist() {
        if (typeof menuStateManager === 'undefined') return;
        const ev = this.events[this.selectedIndex];
        if (!ev) return;
        menuStateManager.setScreen('event-viewer', { eventId: ev.id });
    }

    createUI() {
        if (this.overlay) this.overlay.remove();
        this.overlay = document.createElement('div');
        this.overlay.className = 'content-viewer-overlay';
        this.overlay.innerHTML = `
            <div class="content-viewer-panel">
                <h2 class="content-viewer-title">EVENTS</h2>
                <div class="content-viewer-body" id="evViewerBody">
                    <aside class="content-viewer-list" id="evList"></aside>
                    <div class="pe-resize-handle" aria-hidden="true"></div>
                    <div class="content-viewer-detail" id="evDetail"></div>
                </div>
                <div class="content-viewer-footer">
                    <button type="button" class="pe-btn" id="evClose">CLOSE</button>
                </div>
                <div class="content-viewer-hint">↑↓ Navigate • ESC Close</div>
            </div>
        `;
        document.body.appendChild(this.overlay);
        if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
            VFBgMouseParallax.refresh();
        }
        this.renderList();
        this.renderDetail();
        this.overlay.querySelector('#evClose').addEventListener('click', () => this.close());
        this.mountDevToggles();
    }

    mountDevToggles() {
        this._devToggles = null;
        if (typeof devProfileToggles === 'undefined' || !devProfileToggles.active()) return;
        const footer = this.overlay.querySelector('.content-viewer-footer');
        const hint = this.overlay.querySelector('.content-viewer-hint');
        this._devToggles = devProfileToggles.mount(footer, hint, {
            known: () => {
                const ev = this.events[this.selectedIndex];
                return !!(ev && profileManager.isDiscovered('events', ev.id));
            },
            toggleKnown: () => {
                const ev = this.events[this.selectedIndex];
                if (ev) profileManager.toggleDiscovered('events', ev.id);
            },
            onChange: () => {
                this.events = this.getEventList();
                this.selectedIndex = Math.max(0, Math.min(this.selectedIndex, this.events.length - 1));
                this.renderList();
                this.renderDetail();
                if (this._devToggles) this._devToggles.refresh();
            }
        });
    }

    renderList() {
        const list = this.overlay && this.overlay.querySelector('#evList');
        if (!list) return;
        list.innerHTML = '';
        this.events.forEach((ev, index) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'content-viewer-item' + (index === this.selectedIndex ? ' selected' : '');
            const swatch = `<span class="cv-event-swatch" style="background:${ev.accent || '#888'}"></span>`;
            btn.innerHTML =
                swatch +
                `<span class="cv-item-label">${ev.shortName || ev.name}` +
                (typeof devProfileToggles !== 'undefined' && devProfileToggles.active()
                    ? (typeof devProfileToggles.badgesHtml === 'function'
                        ? devProfileToggles.badgesHtml({
                            known: profileManager.isDiscovered('events', ev.id)
                        })
                        : '')
                    : '') +
                `</span>`;
            btn.addEventListener('click', () => {
                this.selectedIndex = index;
                this.renderList();
                this.renderDetail();
                this.persist();
            });
            list.appendChild(btn);
        });
        const selected = list.querySelector('.content-viewer-item.selected');
        if (selected) selected.scrollIntoView({ block: 'nearest', behavior: 'auto' });
    }

    renderDetail() {
        const root = this.overlay && this.overlay.querySelector('#evDetail');
        const ev = this.events[this.selectedIndex];
        if (!root || !ev) return;
        root.innerHTML = `
            <div class="content-viewer-hero">
                <div class="cv-event-hero-swatch" style="background:${ev.accent || '#888'}"></div>
                <div class="cv-ship-hero-text">
                    <h3 class="content-viewer-name">${ev.name}</h3>
                    <p class="content-viewer-desc">${ev.description || ''}</p>
                </div>
            </div>
            <div class="content-viewer-stats cv-stat-clusters cv-stat-clusters-plain">
                <div class="cv-stat-cluster">
                    <div class="cv-stat-cluster-title">Signal</div>
                    <div class="stat-row"><span class="stat-label">Role</span><span class="stat-value">${String(ev.role || ev.id).toUpperCase()}</span></div>
                    <div class="stat-row"><span class="stat-label">Announce</span><span class="stat-value">${ev.announce || '—'}</span></div>
                    <div class="stat-row"><span class="stat-label">Warn</span><span class="stat-value">${Math.round((ev.announceMs || 0) / 100) / 10}s</span></div>
                </div>
                <div class="cv-stat-cluster">
                    <div class="cv-stat-cluster-title">Counter</div>
                    <p class="content-viewer-desc" style="margin:0">${ev.counter || '—'}</p>
                </div>
            </div>
        `;
    }

    handleKeyDown(e) {
        if (!this.visible) return;
        if (e.key === 'Escape') {
            e.preventDefault();
            this.close();
            return;
        }
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            this.selectedIndex = Math.min(this.events.length - 1, this.selectedIndex + 1);
            this.renderList();
            this.renderDetail();
            this.persist();
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            this.selectedIndex = Math.max(0, this.selectedIndex - 1);
            this.renderList();
            this.renderDetail();
            this.persist();
        }
    }
}

var eventViewerUI = new EventViewerUI();


/* --- js/ui/ability-editor.js --- */
"use strict";

/**
 * Ability Editor — edit shared ability metadata (icon, cluster, type, …).
 * Open: Abilities viewer → EDIT / NEW
 */
var AbilityEditorUI = class AbilityEditorUI {
    constructor() {
        this.visible = false;
        this.returnTo = null;
        this.selectedId = 'player_control';
        this.draft = null;
    }

    init() {
        this.ensureOverlay();
    }

    ensureOverlay() {
        if (document.getElementById('abilityEditorOverlay')) return;

        const overlay = document.createElement('div');
        overlay.id = 'abilityEditorOverlay';
        overlay.className = 'planet-editor-overlay ability-editor-overlay hidden';
        overlay.innerHTML = `
            <div class="planet-editor-panel">
                <div class="planet-editor-header">
                    <h2>ABILITY EDITOR</h2>
                    <div class="planet-editor-planet-select" id="aeTypeSelect"></div>
                </div>
                <div class="planet-editor-body ae-body-single">
                    <div class="planet-editor-controls" id="aeControls"></div>
                </div>
                <div class="planet-editor-footer">
                    <button type="button" class="pe-btn" id="aeNew">NEW</button>
                    <button type="button" class="pe-btn" id="aeReset">RESET</button>
                    <button type="button" class="pe-btn pe-primary" id="aeSave">SAVE</button>
                    <button type="button" class="pe-btn" id="aeClose">CLOSE</button>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);

        overlay.querySelector('#aeSave').addEventListener('click', () => this.save());
        overlay.querySelector('#aeReset').addEventListener('click', () => this.reset());
        overlay.querySelector('#aeNew').addEventListener('click', () => this.createNew());
        overlay.querySelector('#aeClose').addEventListener('click', () => this.hide());

        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && this.visible) {
                e.preventDefault();
                this.hide();
            }
        });
    }

    persistMenuState() {
        if (typeof menuStateManager !== 'undefined' && this.visible) {
            menuStateManager.setScreen('ability-editor', {
                abilityId: this.selectedId,
                returnTo: this.returnTo
            });
        }
    }

    show(abilityId, fromRestore, options) {
        this.ensureOverlay();
        if (abilityId) this.selectedId = String(abilityId);
        if (options && options.returnTo) this.returnTo = options.returnTo;
        else if (!fromRestore) this.returnTo = null;
        this.loadDraft();
        this.visible = true;
        document.getElementById('abilityEditorOverlay').classList.remove('hidden');
        this.renderTypeSelect();
        this.renderControls();
        if (!fromRestore && typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('ability-editor', {
                abilityId: this.selectedId,
                returnTo: this.returnTo
            });
        }
    }

    hide() {
        this.visible = false;
        const el = document.getElementById('abilityEditorOverlay');
        if (el) el.classList.add('hidden');
        const backTo = this.returnTo;
        this.returnTo = null;
        if (backTo === 'ability-viewer' && typeof abilityViewerUI !== 'undefined') {
            abilityViewerUI.show({ abilityId: this.selectedId });
            return;
        }
        if (backTo === 'defense-viewer' && typeof defenseViewerUI !== 'undefined') {
            defenseViewerUI.show({ defenseId: this.selectedId });
            return;
        }
        if (typeof menuStateManager !== 'undefined') {
            const container = document.querySelector('.game-container');
            const inGame = container && container.style.display !== 'none';
            menuStateManager.setScreen(inGame ? 'ingame' : 'start');
        }
    }

    loadDraft() {
        if (typeof abilityConfigManager === 'undefined') {
            this.draft = {
                id: this.selectedId,
                name: this.selectedId,
                description: '',
                icon: '◆',
                cluster: 'other',
                type: 'passive',
                tier: 1,
                uiDescription: '',
                custom: false
            };
            return;
        }
        this.draft = JSON.parse(JSON.stringify(abilityConfigManager.getAbility(this.selectedId)));
    }

    createNew() {
        if (typeof abilityConfigManager === 'undefined') return;
        const ability = abilityConfigManager.createAbility({ name: 'New Ability' });
        this.selectedId = ability.id;
        this.loadDraft();
        this.renderTypeSelect();
        this.renderControls();
        this.persistMenuState();
    }

    renderTypeSelect() {
        const root = document.getElementById('aeTypeSelect');
        if (!root) return;
        root.innerHTML = '';
        const ids = typeof abilityConfigManager !== 'undefined'
            ? abilityConfigManager.getIds()
            : [this.selectedId];
        ids.forEach((id) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'pe-planet-btn' + (id === this.selectedId ? ' active' : '');
            const meta = typeof abilityConfigManager !== 'undefined'
                ? abilityConfigManager.getAbility(id)
                : { icon: '◆', name: id };
            const iconHtml = typeof abilityConfigManager !== 'undefined'
                ? abilityConfigManager.resolveIconHtml(meta.icon, 14, 'cv-ability-icon-img')
                : meta.icon;
            btn.innerHTML = `${iconHtml} <span>${meta.name}</span>`;
            btn.addEventListener('click', () => {
                this.selectedId = id;
                this.loadDraft();
                this.renderTypeSelect();
                this.renderControls();
                this.persistMenuState();
            });
            root.appendChild(btn);
        });
    }

    renderControls() {
        const root = document.getElementById('aeControls');
        if (!root || !this.draft) return;
        root.innerHTML = '';

        const preview = document.createElement('div');
        preview.className = 'ae-preview';
        preview.innerHTML = `<span class="ae-preview-icon">${typeof abilityConfigManager !== 'undefined' ? abilityConfigManager.resolveIconHtml(this.draft.icon || '◆', 32, 'cv-ability-icon-img') : (this.draft.icon || '◆')}</span>` +
            `<span class="ae-preview-name">${this.draft.name || this.draft.id}</span>`;
        root.appendChild(preview);

        root.appendChild(this.makeTextInput('Name', this.draft.name || '', (v) => {
            this.draft.name = v;
            this.updatePreview();
        }));
        root.appendChild(this.makeTextInput('Icon key', this.draft.icon || '', (v) => {
            this.draft.icon = v || '◆';
            this.updatePreview();
        }));
        root.appendChild(this.makeTextInput('Description', this.draft.description || '', (v) => {
            this.draft.description = v;
        }));
        root.appendChild(this.makeTextInput('UI summary', this.draft.uiDescription || '', (v) => {
            this.draft.uiDescription = v;
        }));

        const clusters = (typeof abilityConfigManager !== 'undefined'
            ? abilityConfigManager.clusterOrder.map((c) => c.id)
            : ['core', 'mobility', 'offense', 'defense', 'combat', 'other']);
        root.appendChild(this.makeSelect('Cluster', this.draft.cluster || 'other', clusters, (v) => {
            this.draft.cluster = v;
        }));
        root.appendChild(this.makeSelect('Type', this.draft.type || 'passive', ['passive', 'active'], (v) => {
            this.draft.type = v;
        }));
        root.appendChild(this.makeSlider('Tier', this.draft.tier || 1, 1, 5, 1, (v) => {
            this.draft.tier = Math.round(v);
        }));
    }

    updatePreview() {
        const icon = document.querySelector('#aeControls .ae-preview-icon');
        const name = document.querySelector('#aeControls .ae-preview-name');
        if (icon) {
            icon.innerHTML = typeof abilityConfigManager !== 'undefined'
                ? abilityConfigManager.resolveIconHtml(this.draft.icon || '◆', 32, 'cv-ability-icon-img')
                : (this.draft.icon || '◆');
        }
        if (name) name.textContent = this.draft.name || this.draft.id;
    }

    makeSlider(labelText, value, min, max, step, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const val = document.createElement('span');
        val.className = 'pe-val';
        const format = (v) => (step < 1 ? Number(v).toFixed(2) : String(Math.round(v)));
        val.textContent = format(value);
        const input = document.createElement('input');
        input.type = 'range';
        input.min = String(min);
        input.max = String(max);
        input.step = String(step);
        input.value = String(value);
        input.addEventListener('input', () => {
            const v = Number(input.value);
            val.textContent = format(v);
            onChange(v);
        });
        row.appendChild(label);
        row.appendChild(val);
        row.appendChild(input);
        return row;
    }

    makeSelect(labelText, value, options, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const select = document.createElement('select');
        options.forEach((opt) => {
            const o = document.createElement('option');
            o.value = opt;
            o.textContent = opt;
            if (opt === value) o.selected = true;
            select.appendChild(o);
        });
        select.addEventListener('change', () => onChange(select.value));
        row.appendChild(label);
        row.appendChild(select);
        return row;
    }

    makeTextInput(labelText, value, onChange) {
        const row = document.createElement('div');
        row.className = 'pe-row';
        const label = document.createElement('label');
        label.textContent = labelText;
        const input = document.createElement('input');
        input.type = 'text';
        input.value = value;
        input.className = 'pe-text-input';
        input.addEventListener('input', () => onChange(input.value));
        row.appendChild(label);
        row.appendChild(input);
        return row;
    }

    save() {
        if (typeof abilityConfigManager === 'undefined' || !this.draft) return;
        abilityConfigManager.setAbility(this.selectedId, this.draft);
        this.loadDraft();
        this.renderTypeSelect();
        this.renderControls();
        const header = document.querySelector('#abilityEditorOverlay .planet-editor-header h2');
        if (header) {
            const prev = header.textContent;
            header.textContent = 'SAVED';
            setTimeout(() => { header.textContent = prev || 'ABILITY EDITOR'; }, 700);
        }
    }

    reset() {
        if (typeof abilityConfigManager === 'undefined') return;
        abilityConfigManager.resetAbility(this.selectedId);
        this.loadDraft();
        this.renderControls();
    }
}

var abilityEditorUI = new AbilityEditorUI();
abilityEditorUI.init();


/* --- js/ui/mission-start/core.js --- */
"use strict";

/**
 * Mission start sequence: FIRE TO START → countdown → ships fly in → combat.
 * Overlay chrome follows html[data-faction] / resolveActiveFaction().
 */
var MissionStartManager = class MissionStartManager {
    constructor() {
        this.active = false;
        this.phase = null;
        this.countdownValue = 3;
        this.countdownTimer = 0;
        this.goTimer = 0;
        this.flyInElapsed = 0;
        this.flyInDuration = 1400;
        this.enemyInElapsed = 0;
        this.enemyInDuration = 900;
        this.overlay = null;
        this.textEl = null;
        this.subEl = null;
        this.playerFrom = null;
        this.playerTo = null;
        this.enemyFrom = null;
        this.enemyTo = null;
        this.sideFrom = [];
        this.sideTo = [];
        this._armed = false;
        this._introClock = 0;
    }

    /** Wall-clock countdown/GO — must not depend on the combat RAF (pause / FX remote / park). */
    _clearIntroClock() {
        if (this._introClock) {
            clearTimeout(this._introClock);
            this._introClock = 0;
        }
    }

    _armCountdownClock() {
        this._clearIntroClock();
        const tick = () => {
            this._introClock = 0;
            if (!this.active || this.phase !== 'countdown') return;
            this.countdownValue -= 1;
            if (this.countdownValue > 0) {
                this.setText(String(this.countdownValue), false);
                if (typeof soundManager !== 'undefined' && soundManager.playShoot) {
                    try { soundManager.playShoot(); } catch (e) { /* ignore */ }
                }
                this._introClock = setTimeout(tick, 900);
                return;
            }
            this.setPhase('go');
            this.goTimer = 0;
            this.setText('GO!', false);
            if (typeof soundManager !== 'undefined' && soundManager.playExplosion) {
                try { soundManager.playExplosion(); } catch (e) { /* ignore */ }
            }
            this._introClock = setTimeout(() => {
                this._introClock = 0;
                if (this.active && this.phase === 'go') this.startFlyIn();
            }, 620);
        };
        this._introClock = setTimeout(tick, 900);
    }

    isActive() {
        return !!this.active;
    }

    isAwaitingFire() {
        return this.active && this.phase === 'awaitFire';
    }

    isPlaying() {
        return !this.active;
    }

    arm() {
        this._clearIntroClock();
        this._armed = true;
        this.active = true;
        this.setPhase('awaitFire');
        this.countdownValue = 3;
        this.countdownTimer = 0;
        this.goTimer = 0;
        this.flyInElapsed = 0;
        this.enemyEntry = false;
        this.playerFrom = null;
        this.playerTo = null;
        this.enemyFrom = null;
        this.enemyTo = null;
        this.sideFrom = [];
        this.sideTo = [];
        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = true;
            enemyManager.enemy = null;
            enemyManager.sideEnemies = [];
            enemyManager.scheduleElapsedMs = 0;
            if (Array.isArray(enemyManager.schedule)) {
                enemyManager.schedule.forEach((e) => { e.spawned = false; });
            }
        }
        if (typeof obstacleManager !== 'undefined' && obstacleManager.reset) {
            obstacleManager.reset();
        }
        if (typeof bulletManager !== 'undefined' && bulletManager.reset) {
            bulletManager.reset();
        }
    }

    begin() {
        if (!this._armed) this.arm();
        this.active = true;
        this.setPhase('awaitFire');

        if (typeof playerManager !== 'undefined') {
            if (playerManager.reset) playerManager.reset();
            const p = playerManager.player;
            const h = this.canvasHeight();
            p.y = h + (p.height || 24) + 40;
        }
        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = true;
            enemyManager.enemy = null;
            enemyManager.sideEnemies = [];
            enemyManager.scheduleElapsedMs = 0;
            if (Array.isArray(enemyManager.schedule)) {
                enemyManager.schedule.forEach((e) => { e.spawned = false; });
            }
        }

        this.ensureOverlay();
        this.syncFactionChrome();
        this.setText('FIRE TO START', true);
        this.showOverlay();

        if (typeof levelInfoManager !== 'undefined') {
            if (typeof levelInfoManager.prepareForCombat === 'function') {
                levelInfoManager.prepareForCombat();
            } else if (levelInfoManager.showPanel) {
                levelInfoManager.showPanel();
            }
        }
    }

    canvasWidth() {
        if (typeof game !== 'undefined') {
            return game.internalWidth || game.baseWidth || game.width || 240;
        }
        return 240;
    }

    canvasHeight() {
        if (typeof game !== 'undefined') {
            return game.internalHeight || game.baseHeight || game.height || 300;
        }
        return 300;
    }

    /** Active pilot faction id for overlay chrome. */
    resolveFactionId() {
        if (typeof factionShipStyles !== 'undefined' && factionShipStyles.resolveActiveFaction) {
            return factionShipStyles.resolveActiveFaction();
        }
        return 'terran';
    }

    syncFactionChrome() {
        this.ensureOverlay();
        if (!this.overlay) return;
        const id = this.resolveFactionId();
        this.overlay.dataset.faction = id;
        if (typeof factionShipStyles !== 'undefined' && factionShipStyles.getFactionStyle) {
            const style = factionShipStyles.getFactionStyle(id);
            if (style) {
                this.overlay.style.setProperty('--ms-accent', style.accent || '');
                this.overlay.style.setProperty('--ms-hull', style.hull || '');
                this.overlay.style.setProperty('--ms-edge', style.edge || '');
            }
        }
    }

    setPhase(phase) {
        this.phase = phase;
        if (this.overlay) this.overlay.dataset.phase = phase || '';
    }

    overlayMarkup() {
        return '<div class="mission-start-vignette" aria-hidden="true"></div>' +
            '<div class="mission-start-aura" aria-hidden="true"></div>' +
            '<div class="mission-start-frame" aria-hidden="true">' +
                '<span class="ms-corner ms-tl"></span>' +
                '<span class="ms-corner ms-tr"></span>' +
                '<span class="ms-corner ms-bl"></span>' +
                '<span class="ms-corner ms-br"></span>' +
                '<span class="ms-slash ms-slash-a"></span>' +
                '<span class="ms-slash ms-slash-b"></span>' +
            '</div>' +
            '<div class="mission-start-stack">' +
                '<div class="mission-start-text" id="missionStartText">FIRE TO START</div>' +
                '<div class="mission-start-sub" id="missionStartSub">PRESS FIRE</div>' +
            '</div>';
    }

    ensureOverlay() {
        if (this.overlay && this.overlay.isConnected && this.overlay.querySelector('.mission-start-stack')) {
            this.textEl = this.overlay.querySelector('#missionStartText') || this.textEl;
            this.subEl = this.overlay.querySelector('#missionStartSub') || this.subEl;
            return;
        }
        let el = document.getElementById('missionStartOverlay');
        if (!el) {
            el = document.createElement('div');
            el.id = 'missionStartOverlay';
            el.className = 'mission-start-overlay hidden';
            const stage = document.querySelector('.game-stage') || document.querySelector('.game-canvas-container') || document.body;
            stage.appendChild(el);
        }
        if (!el.querySelector('.mission-start-stack')) {
            el.className = 'mission-start-overlay hidden';
            el.innerHTML = this.overlayMarkup();
        }
        this.overlay = el;
        this.textEl = el.querySelector('#missionStartText') || el.querySelector('.mission-start-text');
        this.subEl = el.querySelector('#missionStartSub');
        this.pixelCanvas = null;
    }

    showOverlay() {
        this.ensureOverlay();
        this.syncFactionChrome();
        if (this.overlay) this.overlay.classList.remove('hidden');
    }

    hideOverlay() {
        if (this.overlay) this.overlay.classList.add('hidden');
    }

    setText(msg, pulse) {
        this.ensureOverlay();
        const raw = String(msg);
        const isCount = !pulse && /^\d+$/.test(raw);
        const isGo = !pulse && raw === 'GO!';
        if (this.textEl) {
            this.textEl.classList.toggle('mission-start-pulse', !!pulse);
            this.textEl.classList.toggle('mission-start-count', isCount);
            this.textEl.classList.toggle('mission-start-go', isGo);
            this.textEl.classList.toggle('mission-start-fire', !!pulse);
            if (isCount || isGo) {
                if (!this.pixelCanvas || !this.pixelCanvas.isConnected) {
                    this.pixelCanvas = document.createElement('canvas');
                    this.pixelCanvas.className = 'mission-start-pixel-canvas';
                    this.textEl.textContent = '';
                    this.textEl.appendChild(this.pixelCanvas);
                }
                this.drawPixelText(isGo ? 'GO' : raw);
            } else {
                this.pixelCanvas = null;
                this.textEl.textContent = raw;
            }
        }
        if (this.subEl) {
            if (pulse) {
                this.subEl.textContent = 'PRESS FIRE';
                this.subEl.hidden = false;
            } else if (isCount) {
                this.subEl.textContent = 'GET READY';
                this.subEl.hidden = false;
            } else if (isGo) {
                this.subEl.textContent = 'ENGAGE';
                this.subEl.hidden = false;
            } else {
                this.subEl.hidden = true;
            }
        }
        if (this.overlay) {
            this.overlay.classList.toggle('is-fire', !!pulse);
            this.overlay.classList.toggle('is-count', isCount);
            this.overlay.classList.toggle('is-go', isGo);
        }
    }

    /** Crisp 5×7 bitmap glyphs scaled with nearest-neighbour — no blurry font. */
    drawPixelText(msg) {
        if (!this.pixelCanvas) return;
        const GLYPHS = {
            '0': ['01110', '10001', '10011', '10101', '11001', '10001', '01110'],
            '1': ['00100', '01100', '00100', '00100', '00100', '00100', '01110'],
            '2': ['01110', '10001', '00001', '00110', '01000', '10000', '11111'],
            '3': ['11110', '00001', '00001', '01110', '00001', '00001', '11110'],
            '4': ['00010', '00110', '01010', '10010', '11111', '00010', '00010'],
            '5': ['11111', '10000', '11110', '00001', '00001', '10001', '01110'],
            '6': ['00110', '01000', '10000', '11110', '10001', '10001', '01110'],
            '7': ['11111', '00001', '00010', '00100', '01000', '01000', '01000'],
            '8': ['01110', '10001', '10001', '01110', '10001', '10001', '01110'],
            '9': ['01110', '10001', '10001', '01111', '00001', '00010', '01100'],
            'G': ['01110', '10001', '10000', '10111', '10001', '10001', '01110'],
            'O': ['01110', '10001', '10001', '10001', '10001', '10001', '01110']
        };
        const canvas = this.pixelCanvas;
        const chars = String(msg).toUpperCase().split('').filter((c) => GLYPHS[c]);
        // 1px margin + 1px drop shadow; 1px gap between digits.
        canvas.width = Math.max(1, chars.length * 6 + 2);
        canvas.height = 10;
        const ctx = canvas.getContext('2d');
        ctx.imageSmoothingEnabled = false;
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        const color = getComputedStyle(this.textEl).color;
        const paint = (ox, oy, fill, alpha) => {
            ctx.globalAlpha = alpha;
            ctx.fillStyle = fill;
            chars.forEach((c, i) => {
                GLYPHS[c].forEach((row, y) => {
                    for (let x = 0; x < 5; x++) {
                        if (row[x] === '1') ctx.fillRect(1 + i * 6 + x + ox, 1 + y + oy, 1, 1);
                    }
                });
            });
        };
        paint(1, 1, '#000', 0.55);
        paint(0, 0, color, 1);
        ctx.globalAlpha = 1;
        // Restart the per-second progress bar and pop-in animation.
        const el = this.textEl;
        el.classList.remove('mission-start-tick');
        void el.offsetWidth;
        el.classList.add('mission-start-tick');
    }

    onFire() {
        if (!this.active || this.phase !== 'awaitFire') return false;
        this.setPhase('countdown');
        this.countdownValue = 3;
        this.countdownTimer = 0;
        this.goTimer = 0;
        this.syncFactionChrome();
        this.setText('3', false);
        if (typeof soundManager !== 'undefined' && soundManager.playShoot) {
            try { soundManager.playShoot(); } catch (e) { /* ignore */ }
        }
        this._armCountdownClock();
        return true;
    }

    update(deltaTime) {
        if (!this.active) return;

        // Countdown / GO advance via _armCountdownClock (setTimeout), so pause / FX remote
        // / parked combat RAF cannot freeze the "3…2…1…GO" beat.
        if (this.phase === 'countdown' || this.phase === 'go') {
            return;
        }

        if (this.phase === 'preparingFlyIn') {
            return;
        }

        if (this.phase === 'flyIn') {
            this.flyInElapsed += deltaTime;
            const t = Math.min(1, this.flyInElapsed / this.flyInDuration);
            const ease = 1 - Math.pow(1 - t, 3);
            // Enemies wait off screen until the player is out of the hatch and in control.
            this.applyPlayerFlyIn(ease);
            this.applyEnemyFlyIn(0);
            if (t >= 1) {
                this.complete();
            }
        }
    }

    /**
     * After the intro: champion and side craft glide in from off screen while the player already flies.
     * Called from the game loop after enemyManager.update so the entry path wins over AI movement.
     */
    updateEnemyEntry(deltaTime) {
        if (!this.enemyEntry) return;
        this.enemyInElapsed += deltaTime;
        const t = Math.min(1, this.enemyInElapsed / this.enemyInDuration);
        this.applyEnemyFlyIn(1 - Math.pow(1 - t, 3));
        if (t >= 1) this.endEnemyEntry();
    }

    endEnemyEntry() {
        this.enemyEntry = false;
        if (typeof enemyManager === 'undefined') return;
        if (enemyManager.enemy) enemyManager.enemy.introEntry = false;
        (enemyManager.sideEnemies || []).forEach((s) => { s.introEntry = false; });
    }

    startFlyIn() {
        this._clearIntroClock();
        this.setPhase('preparingFlyIn');
        this.hideOverlay();
        this.prepareFlyIn().catch((err) => {
            console.error('Mission fly-in failed:', err);
            this.complete();
        });
    }
}


/* --- js/ui/mission-start/prepare-fly-in.js --- */
"use strict";

// MissionStartManager methods, split from mission-start.js.
extendClass(MissionStartManager, {
    async prepareFlyIn() {
        const w = this.canvasWidth();
        const h = this.canvasHeight();

        if (typeof playerManager !== 'undefined') {
            if (playerManager.reset) playerManager.reset();
            const p = playerManager.player;
            this.playerTo = { x: p.x, y: p.y };
            this.playerFrom = { x: p.x, y: h + p.height + 36 };
            p.x = this.playerFrom.x;
            p.y = this.playerFrom.y;
        }

        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = false;
            enemyManager.scheduleElapsedMs = 0;
            if (!Array.isArray(enemyManager.schedule) || !enemyManager.schedule.length) {
                const type = enemyManager.currentShipType || 'enemyBasic';
                enemyManager.setEnemySchedule([{
                    id: 'main',
                    type: type,
                    champion: true,
                    level: 2,
                    spawnAt: 0
                }], {
                    planetId: (typeof game !== 'undefined' && game.coreLevelManager &&
                        game.coreLevelManager.getCurrentLevel &&
                        game.coreLevelManager.getCurrentLevel() &&
                        game.coreLevelManager.getCurrentLevel().planetId) || 'mars'
                });
            }
            if (Array.isArray(enemyManager.schedule)) {
                enemyManager.schedule.forEach((e) => { e.spawned = false; });
            }
            enemyManager.enemy = null;
            enemyManager.sideEnemies = [];
            const state = { width: w, height: h };

            // Spawn due-at-0 entries (respect cluster wave times); await champion model
            const clusterWaveAt = {};
            (enemyManager.schedule || []).forEach((e) => {
                const c = e.cluster || 'alpha';
                const at = Number(e.spawnAt != null ? e.spawnAt : 0);
                if (clusterWaveAt[c] == null || at < clusterWaveAt[c]) {
                    clusterWaveAt[c] = at;
                }
            });
            let due = (enemyManager.schedule || []).filter((entry) => {
                if (entry.spawned) return false;
                const at = Number(entry.spawnAt != null ? entry.spawnAt : 0);
                const waveAt = clusterWaveAt[entry.cluster || 'alpha'];
                const dueAt = Math.min(at, waveAt != null ? waveAt : at);
                return dueAt <= 0;
            });
            // Always bring at least the champion in during fly-in
            if (!due.length && enemyManager.schedule.length) {
                const champ = enemyManager.schedule.find((e) => e.champion) || enemyManager.schedule[0];
                if (champ) due = [champ];
            }
            for (const entry of due) {
                entry.spawned = true;
                if (entry.champion) {
                    await enemyManager.spawnChampionFromEntry(entry);
                } else {
                    enemyManager.spawnScheduledNormal(entry, state);
                }
            }

            if (enemyManager.enemy) {
                const e = enemyManager.enemy;
                this.enemyTo = { x: e.x, y: e.y };
                this.enemyFrom = { x: e.x, y: -e.height - 24 };
                e.x = this.enemyFrom.x;
                e.y = this.enemyFrom.y;
            } else {
                this.enemyFrom = null;
                this.enemyTo = null;
            }

            this.sideFrom = [];
            this.sideTo = [];
            (enemyManager.sideEnemies || []).forEach((s, i) => {
                const to = { x: s.x, y: s.y };
                let from;
                if (s.isEscort) {
                    from = { x: to.x, y: -s.height - 20 - i * 12 };
                } else if (s.speed < 0) {
                    from = { x: w + s.width + 30 + i * 10, y: to.y };
                } else {
                    from = { x: -s.width - 30 - i * 10, y: to.y };
                }
                this.sideFrom.push(from);
                this.sideTo.push(to);
                s.x = from.x;
                s.y = from.y;
            });
        }

        if (!this.active) return;
        if (this.setPhase) this.setPhase('flyIn');
        else this.phase = 'flyIn';
        this.flyInElapsed = 0;
    },

    applyFlyIn(ease) {
        this.applyPlayerFlyIn(ease);
        this.applyEnemyFlyIn(ease);
    },

    applyPlayerFlyIn(ease) {
        if (this.playerFrom && this.playerTo && typeof playerManager !== 'undefined') {
            const p = playerManager.player;
            p.x = this.playerFrom.x + (this.playerTo.x - this.playerFrom.x) * ease;
            p.y = this.playerFrom.y + (this.playerTo.y - this.playerFrom.y) * ease;
        }
    },

    /** Champion and side craft fly in from off screen (0 = still outside). */
    applyEnemyFlyIn(ease) {
        if (this.enemyFrom && this.enemyTo && typeof enemyManager !== 'undefined' && enemyManager.enemy) {
            const e = enemyManager.enemy;
            e.x = this.enemyFrom.x + (this.enemyTo.x - this.enemyFrom.x) * ease;
            e.y = this.enemyFrom.y + (this.enemyTo.y - this.enemyFrom.y) * ease;
        }
        if (typeof enemyManager !== 'undefined' && enemyManager.sideEnemies) {
            enemyManager.sideEnemies.forEach((s, i) => {
                const from = this.sideFrom[i];
                const to = this.sideTo[i];
                if (!from || !to) return;
                s.x = from.x + (to.x - from.x) * ease;
                s.y = from.y + (to.y - from.y) * ease;
            });
        }
    },

    complete() {
        if (this._clearIntroClock) this._clearIntroClock();
        this.applyPlayerFlyIn(1);
        // Enemies enter only once the player can fly (see updateEnemyEntry).
        this.enemyInElapsed = 0;
        this.enemyEntry = true;
        if (typeof enemyManager !== 'undefined') {
            if (enemyManager.enemy && this.enemyFrom) enemyManager.enemy.introEntry = true;
            (enemyManager.sideEnemies || []).forEach((s, i) => { if (this.sideFrom && this.sideFrom[i]) s.introEntry = true; });
        }
        this.active = false;
        this.phase = null;
        this._armed = false;
        this.hideOverlay();

        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = false;
        }

        if (typeof levelInfoManager !== 'undefined' && levelInfoManager.startLevel) {
            levelInfoManager.startLevel();
        }
        if (typeof game !== 'undefined' && game.gameState && game.gameState.stats) {
            game.gameState.stats.levelStartTime = Date.now();
        }
    },

    cancel() {
        if (this._clearIntroClock) this._clearIntroClock();
        this.endEnemyEntry();
        this.active = false;
        this.phase = null;
        this._armed = false;
        this.hideOverlay();
        if (typeof enemyManager !== 'undefined') {
            enemyManager.spawnFrozen = false;
        }
    },
});


