// MissionStartManager is defined in mission-start/core.js and extended by the other files in mission-start/,
// which index.html loads before this file.
var missionStartManager = new MissionStartManager();


/* --- js/ui/ship-renderer.js --- */
"use strict";

// Ship Renderer - Centralized ship rendering functionality
var ShipRenderer = class ShipRenderer {
    constructor() {
        this.spriteLoader = null;
        this.colorManager = null;
    }

    // Initialize with dependencies
    init() {
        if (typeof spriteLoader !== 'undefined') {
            this.spriteLoader = spriteLoader;
        }
        if (typeof colorManager !== 'undefined') {
            this.colorManager = colorManager;
        }
    }

    resolveFillStyle(color) {
        if (!color || color === 'transparent') return color;
        if (typeof color === 'string' && color.indexOf('var(') === 0) {
            const match = color.match(/var\(\s*(--[^),\s]+)/);
            if (match) {
                const value = getComputedStyle(document.documentElement).getPropertyValue(match[1]).trim();
                if (value) return value;
            }
            if (/secondary|800|700|600/.test(color)) return '#666666';
            if (/400|300|200|100/.test(color)) return '#cccccc';
            return '#999999';
        }
        return color;
    }

    // Render ship preview to canvas
    // fillBoost: >1 zooms the fit-to-canvas scale in past pure "contain" so
    // small decorative previews (e.g. the galaxy map mini canvas) can sit
    // closer to the edges instead of leaving a big margin; wingtips/aft may
    // clip slightly off-canvas at higher values, so it defaults to 1 (no
    // clipping) for editor/full previews that need the whole hull visible.
    renderShipPreview(canvas, ship, scale = 3, fillBoost = 1) {
        const ctx = canvas.getContext('2d');
        
        // Clear canvas with transparent background
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        
        // Ensure canvas background is transparent
        canvas.style.backgroundColor = 'transparent';
        ctx.imageSmoothingEnabled = false;
        if (ctx.mozImageSmoothingEnabled !== undefined) ctx.mozImageSmoothingEnabled = false;
        if (ctx.webkitImageSmoothingEnabled !== undefined) ctx.webkitImageSmoothingEnabled = false;
        if (ctx.msImageSmoothingEnabled !== undefined) ctx.msImageSmoothingEnabled = false;
        
        // Get color overlay for non-transparent areas only
        let colorOverlay = null;
        let overlayIntensity = 0;
        
        if (this.colorManager) {
            colorOverlay = this.resolveFillStyle(this.colorManager.getCurrentOverlayColor());
            overlayIntensity = this.colorManager.getCurrentOverlayIntensity();
        }

        // Modular ships: fit core + modules into canvas
        if (ship && ship.modular && ship.layout) {
            const loader = (typeof graphicsManager !== 'undefined' && graphicsManager.shipAssetLoader)
                || (typeof shipAssetLoader !== 'undefined' ? shipAssetLoader : null);
            if (loader && loader.renderShip) {
                const shipW = ship.width || 16;
                const shipH = ship.height || 12;
                const fit = Math.min(canvas.width / shipW, canvas.height / shipH) * Math.max(1, fillBoost);
                const rw = shipW * fit;
                const rh = shipH * fit;
                const ox = (canvas.width - rw) / 2;
                const oy = (canvas.height - rh) / 2;
                const gp = (typeof uiAppearanceManager !== 'undefined' && uiAppearanceManager.getGlobalPixelPx)
                    ? uiAppearanceManager.getGlobalPixelPx() : 0;
                const prevCell = loader.globalVoxelCell;
                if (gp > 0 && canvas.clientWidth > 0) {
                    // One art pixel == gp screen px regardless of canvas CSS scaling.
                    loader.globalVoxelCell = Math.max(0.25, gp * canvas.width / canvas.clientWidth);
                }
                try {
                    loader.renderShip(ctx, ship, ox, oy, fit, colorOverlay, overlayIntensity);
                } finally {
                    loader.globalVoxelCell = prevCell;
                }
                return;
            }
        }
        
        // Check if this is an enemy ship (needs vertical flip)
        const isEnemyShip = this.isEnemyShip(ship);
        
        // Try to use PNG sprite first, fallback to pixel sprite
        const spriteName = this.getSpriteNameForShip(ship);
        const sprite = this.spriteLoader && spriteName ? this.spriteLoader.getSprite(spriteName) : null;
        
        if (sprite) {
            // Use PNG sprite - maintain aspect ratio
            const spriteAspect = sprite.width / sprite.height;
            const canvasAspect = canvas.width / canvas.height;
            
            let renderWidth, renderHeight, offsetX, offsetY;
            
            if (spriteAspect > canvasAspect) {
                // Sprite is wider - fit to width
                renderWidth = canvas.width;
                renderHeight = canvas.width / spriteAspect;
                offsetX = 0;
                offsetY = (canvas.height - renderHeight) / 2;
            } else {
                // Sprite is taller - fit to height
                renderHeight = canvas.height;
                renderWidth = canvas.height * spriteAspect;
                offsetX = (canvas.width - renderWidth) / 2;
                offsetY = 0;
            }
            
            // Ensure transparency is preserved
            ctx.globalCompositeOperation = 'source-over';
            ctx.globalAlpha = 1.0;
            
            // Apply vertical flip for enemy ships
            if (isEnemyShip) {
                ctx.save();
                ctx.translate(offsetX + renderWidth / 2, offsetY + renderHeight / 2);
                ctx.scale(1, -1); // Vertical flip
                ctx.translate(-renderWidth / 2, -renderHeight / 2);
                this.spriteLoader.renderSprite(ctx, spriteName, 0, 0, renderWidth, renderHeight, colorOverlay, overlayIntensity);
                ctx.restore();
            } else {
                this.spriteLoader.renderSprite(ctx, spriteName, offsetX, offsetY, renderWidth, renderHeight, colorOverlay, overlayIntensity);
            }
        } else {
            // Fallback to pixel sprite - center and scale to fit
            const shipW = ship.width || (ship.sprite && ship.sprite[0] && ship.sprite[0].length) || 16;
            const shipH = ship.height || (ship.sprite && ship.sprite.length) || 12;
            const maxScale = Math.min(canvas.width / shipW, canvas.height / shipH);
            const scaledWidth = shipW * maxScale;
            const scaledHeight = shipH * maxScale;
            const centerX = (canvas.width - scaledWidth) / 2;
            const centerY = (canvas.height - scaledHeight) / 2;
            this.renderPixelShip(ctx, ship, centerX, centerY, maxScale, colorOverlay, overlayIntensity, isEnemyShip);
        }
    }

    // Render pixel-based ship (fallback)
    renderPixelShip(ctx, ship, offsetX, offsetY, scale, colorOverlay, overlayIntensity, isEnemyShip = false) {
        const sprite = ship.sprite;
        const colors = ship.colors || {};
        if (!sprite || !sprite.length) return;

        const cols = sprite[0].length;
        const rows = sprite.length;
        const destW = (ship.width || cols) * scale;
        const destH = (ship.height || rows) * scale;
        const pw = destW / Math.max(1, cols);
        const ph = destH / Math.max(1, rows);

        const tint = (base) => {
            if (!colorOverlay || !(overlayIntensity > 0)) return base;
            if (typeof colorPalette !== 'undefined' && colorPalette.applyColorOverlay) {
                return colorPalette.applyColorOverlay(base, colorOverlay, overlayIntensity);
            }
            return base;
        };

        ctx.save();
        ctx.globalCompositeOperation = 'source-over';
        ctx.globalAlpha = 1.0;

        if (isEnemyShip) {
            ctx.translate(offsetX + destW / 2, offsetY + destH / 2);
            ctx.scale(1, -1);
            ctx.translate(-(offsetX + destW / 2), -(offsetY + destH / 2));
        }

        for (let row = 0; row < rows; row++) {
            for (let col = 0; col < sprite[row].length; col++) {
                const pixel = sprite[row][col];
                if (!pixel) continue;
                ctx.fillStyle = tint(this.resolveFillStyle(colors[pixel] || '#888888'));
                ctx.fillRect(
                    offsetX + col * pw,
                    offsetY + row * ph,
                    Math.ceil(pw),
                    Math.ceil(ph)
                );
            }
        }

        ctx.restore();

        // Engine glow — flip with ship so aft stays aft after orientation
        if (ship.engineGlow && ship.engineGlow.positions) {
            ctx.save();
            if (isEnemyShip) {
                ctx.translate(offsetX + destW / 2, offsetY + destH / 2);
                ctx.scale(1, -1);
                ctx.translate(-(offsetX + destW / 2), -(offsetY + destH / 2));
            }
            ship.engineGlow.positions.forEach((pos) => {
                ctx.globalAlpha = (pos.intensity || 0.6) * 0.8;
                ctx.fillStyle = pos.color || ship.engineGlow.color || '#9ab0c0';
                ctx.fillRect(
                    offsetX + pos.x * pw,
                    offsetY + pos.y * ph,
                    Math.ceil(pw),
                    Math.ceil(ph)
                );
            });
            ctx.restore();
            ctx.globalAlpha = 1.0;
        }
    }

    // Check if ship is an enemy ship
    isEnemyShip(ship) {
        if (!ship) return false;
        if (ship.forceEnemyOrientation) return true;

        // Check by sprite name patterns
        const spriteName = this.getSpriteNameForShip(ship);
        if (spriteName) {
            return spriteName.includes('enemy-') || spriteName.includes('enemy_');
        }
        
        // Check by ship type/name patterns
        const shipName = ship.name ? ship.name.toLowerCase() : '';
        return shipName.includes('enemy') || shipName.includes('fighter') || 
               shipName.includes('battleship') || shipName.includes('cruiser') ||
               shipName.includes('interceptor') || shipName.includes('scout') ||
               shipName.includes('destroyer') || shipName.includes('carrier') ||
               shipName.includes('frigate') || shipName.includes('corvette') ||
               shipName.includes('gunship') || shipName.includes('dreadnought') ||
               shipName.includes('bomber') || shipName.includes('stealth');
    }

    // Get sprite name for ship
    getSpriteNameForShip(ship) {
        if (!ship) return null;
        
        const type = ship.type;
        const modelClass = ship.modelClass;
        
        if (type === 'player') {
            switch (modelClass) {
                case 'starfighter': return 'player-starfighter';
                case 'heavy_fighter': return 'player-heavy-fighter';
                case 'assault': return 'player-assault';
                case 'interceptor': return 'player-interceptor';
                case 'bomber': return 'player-bomber';
                case 'stealth': return 'player-stealth';
                default: return 'player-starfighter';
            }
        } else if (type === 'enemy') {
            switch (modelClass) {
                case 'fighter': return 'enemy-fighter';
                case 'battleship': return 'enemy-battleship';
                case 'cruiser': return 'enemy-cruiser';
                case 'interceptor': return 'enemy-interceptor';
                case 'scout': return 'enemy-scout';
                default: return 'enemy-fighter';
            }
        }
        
        return null;
    }
}

// Global ship renderer instance
var shipRenderer = new ShipRenderer();


/* --- js/ui/galaxy-selection.js --- */
"use strict";

/**
 * Screen 1 — Galaxy selection with per-profile progress.
 */
var GalaxySelectionManager = class GalaxySelectionManager {
    constructor() {
        this.isVisible = false;
        this.selectedIndex = 0;
        this.galaxies = [];
        this.overlay = null;
        this._keyHandler = null;
        this.onConfirm = null;
        this.onCancel = null;
    }

    isGalaxyDiscovered(galaxyId, planets) {
        if (typeof startScreenManager !== 'undefined' && startScreenManager.devMode) {
            return true;
        }
        if (!(planets && planets.length)) return false;
        if (typeof profileManager === 'undefined' || !profileManager.getActiveProfile()) {
            return true;
        }
        const progress = profileManager.getGalaxyProgress(galaxyId);
        return (progress.unlockedCount || 0) > 0 || (progress.clearedCount || 0) > 0;
    }

    refreshGalaxies() {
        if (typeof planetConfigManager !== 'undefined' && planetConfigManager.getGalaxyTree) {
            this.galaxies = planetConfigManager.getGalaxyTree()
                .filter(g => this.isGalaxyDiscovered(g.id, g.planets))
                .map(g => {
                    const progress = (typeof profileManager !== 'undefined')
                        ? profileManager.getGalaxyProgress(g.id)
                        : { label: '0/0 CLEARED', totalPlanets: (g.planets || []).length, clearedCount: 0 };
                    return {
                        id: g.id,
                        name: g.name,
                        planetCount: (g.planets || []).length,
                        empty: false,
                        locked: false,
                        progressLabel: progress.label,
                        clearedCount: progress.clearedCount,
                        totalPlanets: progress.totalPlanets
                    };
                });
        } else {
            this.galaxies = [
                { id: 'milky_way', name: 'MILKY WAY', planetCount: 5, empty: false, locked: false, progressLabel: '0/5 CLEARED', clearedCount: 0, totalPlanets: 5 }
            ];
        }
        if (this.selectedIndex >= this.galaxies.length) {
            this.selectedIndex = Math.max(0, this.galaxies.length - 1);
        }
    }

    show(options) {
        this.isVisible = true;
        this.onConfirm = options && options.onConfirm;
        this.onCancel = options && options.onCancel;
        this.refreshGalaxies();
        this.createUI();
        if (typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('galaxySelect');
        }
    }

    hide() {
        this.isVisible = false;
        if (this._keyHandler) {
            document.removeEventListener('keydown', this._keyHandler);
            this._keyHandler = null;
        }
        if (this.overlay) {
            this.overlay.remove();
            this.overlay = null;
        }
    }

    galaxyLogoKey(galaxyId) {
        const id = String(galaxyId || '').toLowerCase().replace(/[^a-z0-9_]/g, '_');
        const keyed = 'galaxy_' + id;
        if (typeof IconSprites !== 'undefined' && IconSprites[keyed]) return keyed;
        const camel = 'galaxy' + id.split('_').map(p => p.charAt(0).toUpperCase() + p.slice(1)).join('');
        if (typeof IconSprites !== 'undefined' && IconSprites[camel]) return camel;
        return 'galaxyDefault';
    }

    galaxyLogoHtml(galaxy) {
        if (galaxy.empty) {
            return '<div class="galaxy-belt-empty">EMPTY</div>';
        }
        if (typeof iconRenderer !== 'undefined' && iconRenderer.imgHtml) {
            const key = this.galaxyLogoKey(galaxy.id);
            const img = iconRenderer.imgHtml(key, 48, 'galaxy-thumb-logo');
            if (img) return img;
        }
        return '<div class="galaxy-belt-empty">★</div>';
    }

    createUI() {
        if (this.overlay) this.overlay.remove();

        this.overlay = document.createElement('div');
        this.overlay.className = 'galaxy-selection-overlay';
        this.overlay.innerHTML = `
            <div class="galaxy-selection-content">
                <h2 class="galaxy-selection-title">SELECT GALAXY</h2>
                <div class="galaxy-belt-container">
                    <div class="galaxy-belt">
                        ${this.galaxies.map((g, index) => `
                            <div class="galaxy-belt-item ${index === this.selectedIndex ? 'selected' : ''} ${g.locked ? 'locked' : ''}" data-index="${index}">
                                <div class="galaxy-belt-thumbs">${this.galaxyLogoHtml(g)}</div>
                                <div class="galaxy-belt-name">${g.name}</div>
                                <div class="galaxy-belt-progress">${g.locked ? 'LOCKED' : g.progressLabel}</div>
                            </div>
                        `).join('')}
                    </div>
                </div>
                <div class="galaxy-details-container">
                    <div class="galaxy-info-detailed">
                        <h3 class="galaxy-name-large">${this.galaxies[this.selectedIndex]?.name || ''}</h3>
                        <div class="galaxy-stats-detailed">
                            <div class="stat-row">
                                <span class="stat-label">Planets:</span>
                                <span class="stat-value galaxy-stat-planets">${this.galaxies[this.selectedIndex]?.planetCount || 0}</span>
                            </div>
                            <div class="stat-row">
                                <span class="stat-label">Progress:</span>
                                <span class="stat-value galaxy-stat-progress">${this.galaxies[this.selectedIndex]?.progressLabel || '—'}</span>
                            </div>
                        </div>
                        ${this.galaxies[this.selectedIndex]?.locked ? '<div class="locked-indicator-large">GALAXY LOCKED</div>' : ''}
                    </div>
                </div>
                <div class="galaxy-selection-actions">
                    <button class="action-button" id="gsConfirm">ENTER GALAXY</button>
                    <button class="action-button secondary" id="gsCancel">BACK</button>
                </div>
                <div class="galaxy-selection-instructions">
                    <p>← → Select | ENTER Confirm | ESC Back</p>
                </div>
            </div>
        `;
        document.body.appendChild(this.overlay);
        this.bindEvents();
    }

    bindEvents() {
        this.overlay.querySelectorAll('.galaxy-belt-item').forEach(item => {
            item.addEventListener('click', () => {
                const idx = parseInt(item.dataset.index, 10);
                if (Number.isNaN(idx)) return;
                this.selectIndex(idx);
            });
            item.addEventListener('dblclick', () => {
                const idx = parseInt(item.dataset.index, 10);
                if (Number.isNaN(idx)) return;
                this.selectIndex(idx);
                this.confirm();
            });
        });

        const confirmBtn = this.overlay.querySelector('#gsConfirm');
        const cancelBtn = this.overlay.querySelector('#gsCancel');
        if (confirmBtn) confirmBtn.addEventListener('click', () => this.confirm());
        if (cancelBtn) cancelBtn.addEventListener('click', () => this.cancel());

        this._keyHandler = (e) => {
            if (!this.isVisible) return;
            if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                e.preventDefault();
                this.navigate(-1);
            } else if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
                e.preventDefault();
                this.navigate(1);
            } else if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                this.confirm();
            } else if (e.key === 'Escape') {
                e.preventDefault();
                this.cancel();
            }
        };
        document.addEventListener('keydown', this._keyHandler);
    }

    navigate(dir) {
        if (!this.galaxies.length) return;
        let idx = this.selectedIndex + dir;
        while (idx >= 0 && idx < this.galaxies.length && this.galaxies[idx].locked) {
            idx += dir;
        }
        if (idx < 0 || idx >= this.galaxies.length) return;
        this.selectIndex(idx);
    }

    selectIndex(index) {
        if (index < 0 || index >= this.galaxies.length) return;
        this.selectedIndex = index;
        this.overlay.querySelectorAll('.galaxy-belt-item').forEach((el, i) => {
            el.classList.toggle('selected', i === index);
        });
        const g = this.galaxies[index];
        const nameEl = this.overlay.querySelector('.galaxy-name-large');
        const planetsEl = this.overlay.querySelector('.galaxy-stat-planets');
        const progressEl = this.overlay.querySelector('.galaxy-stat-progress');
        if (nameEl) nameEl.textContent = g.name;
        if (planetsEl) planetsEl.textContent = String(g.planetCount);
        if (progressEl) progressEl.textContent = g.locked ? 'LOCKED' : g.progressLabel;

        let locked = this.overlay.querySelector('.locked-indicator-large');
        const info = this.overlay.querySelector('.galaxy-info-detailed');
        if (g.locked && !locked && info) {
            locked = document.createElement('div');
            locked.className = 'locked-indicator-large';
            locked.textContent = 'GALAXY LOCKED';
            info.appendChild(locked);
        } else if (!g.locked && locked) {
            locked.remove();
        }
    }

    confirm() {
        const g = this.galaxies[this.selectedIndex];
        if (!g || g.locked) return;
        const cb = this.onConfirm;
        this.hide();
        if (typeof cb === 'function') cb(g.id);
    }

    cancel() {
        const cb = this.onCancel;
        this.hide();
        if (typeof cb === 'function') cb();
    }
}

var galaxySelectionManager = new GalaxySelectionManager();
window.galaxySelectionManager = galaxySelectionManager;


/* --- js/core/universe-save.js --- */
"use strict";

/**
 * Universe savegame: ALL galaxies (planets, maps, control, custom clusters /
 * patterns, faction standing) together with every pilot living in them, as
 * one JSON file. Download it, send it to someone, upload it to continue there.
 *
 *   universeSave.download()            // → glxee-universe-YYYY-MM-DD.json
 *   universeSave.upload()              // file picker → confirm → restore → reload
 *
 * Restoring writes the same localStorage keys the managers use and reloads the
 * page, so every manager starts clean from the loaded data.
 */
var UNIVERSE_FORMAT = 'glxee-universe';
var UNIVERSE_VERSION = 1;
// localStorage key → what it holds. Galaxies + their planets first, then the pilots.
var UNIVERSE_KEYS = [
    { key: 'vf_galaxies_v1', part: 'galaxies' },
    { key: 'vf_planet_configs_v1', part: 'planets' },
    { key: 'vf_custom_clusters_v1', part: 'clusters' },
    { key: 'vf_custom_patterns_v1', part: 'patterns' },
    { key: 'vf_faction_state_v1', part: 'factionState' },
    { key: 'vf_profiles_v1', part: 'players' }
];

var universeSave = {
    /** Everything that belongs to the universe, parsed, as one plain object. */
    collect() {
        const data = {};
        UNIVERSE_KEYS.forEach(({ key, part }) => {
            try {
                const raw = localStorage.getItem(key);
                if (raw != null) data[part] = JSON.parse(raw);
            } catch (e) { /* unreadable part: leave it out */ }
        });
        // Make sure the live state is what gets written, not a stale copy.
        if (typeof planetConfigManager !== 'undefined' && planetConfigManager.save) planetConfigManager.save();
        if (typeof profileManager !== 'undefined' && profileManager.save) profileManager.save();
        const fresh = {};
        UNIVERSE_KEYS.forEach(({ key, part }) => {
            try {
                const raw = localStorage.getItem(key);
                if (raw != null) fresh[part] = JSON.parse(raw);
            } catch (e) { if (data[part] !== undefined) fresh[part] = data[part]; }
        });
        return {
            format: UNIVERSE_FORMAT,
            version: UNIVERSE_VERSION,
            savedAt: new Date().toISOString(),
            summary: {
                galaxies: Object.keys(fresh.galaxies || {}).length,
                players: ((fresh.players && fresh.players.profiles) || []).map((p) => p.name)
            },
            data: fresh
        };
    },

    fileName() {
        return `glxee-universe-${new Date().toISOString().slice(0, 10)}.json`;
    },

    download() {
        const json = JSON.stringify(this.collect(), null, 2);
        const blob = new Blob([json], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = this.fileName();
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
    },

    /** Parses + validates a universe file's text; returns the savegame or throws. */
    parse(text) {
        let doc;
        try { doc = JSON.parse(text); } catch (e) { throw new Error('This is not a JSON file.'); }
        if (!doc || doc.format !== UNIVERSE_FORMAT || !doc.data || typeof doc.data !== 'object') {
            throw new Error('This is not a GLXEE universe file.');
        }
        if (Number(doc.version) > UNIVERSE_VERSION) {
            throw new Error('This universe file is from a newer version of the game.');
        }
        if (!doc.data.galaxies || typeof doc.data.galaxies !== 'object') {
            throw new Error('The file contains no galaxies.');
        }
        return doc;
    },

    /** Writes the savegame into storage (replacing the current universe + pilots). */
    apply(doc) {
        UNIVERSE_KEYS.forEach(({ key, part }) => {
            if (doc.data[part] === undefined) localStorage.removeItem(key);
            else localStorage.setItem(key, JSON.stringify(doc.data[part]));
        });
        // Start clean on the start screen with the loaded pilots.
        try {
            sessionStorage.removeItem('vf_menu_state_v1');
            localStorage.removeItem('vf_start_menu_state_v1');
        } catch (e) { /* ignore */ }
    },

    /** Validates a picked / dropped file, asks for confirmation, restores and reloads. */
    async loadFile(file) {
        if (!file) return;
        try {
            const doc = this.parse(await file.text());
            const names = (doc.summary && doc.summary.players) || [];
            const msg = `Load universe "${file.name}"?\n` +
                `${Object.keys(doc.data.galaxies).length} galaxies, ` +
                `${names.length ? names.length + ' pilots (' + names.join(', ') + ')' : 'no pilots'}.\n` +
                'This REPLACES your current galaxies and pilots.';
            const ok = await uiDialog.confirm(msg, { title: 'LOAD UNIVERSE', okLabel: 'LOAD', danger: true });
            if (!ok) return;
            this.apply(doc);
            location.reload();
        } catch (err) {
            uiDialog.alert(String(err && err.message || err), { title: 'LOAD UNIVERSE' });
        }
    },

    /** File picker → loadFile. */
    upload() {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'application/json,.json';
        input.style.display = 'none';
        input.addEventListener('change', () => {
            const file = input.files && input.files[0];
            input.remove();
            this.loadFile(file);
        });
        document.body.appendChild(input);
        input.click();
    }
};
window.universeSave = universeSave;


/* --- js/ui/onboarding.js --- */
"use strict";

/**
 * First-run onboarding: Faction homeworld → Pilot → Callsign → Scrap Fighter.
 */
var OnboardingManager = class OnboardingManager {
    constructor() {
        this.isVisible = false;
        this.overlay = null;
        this._keyHandler = null;
        this.step = 'story'; // story | pilot | name | scrap
        this.onComplete = null;
        this._pendingName = '';
        this._pendingFaction = 'terran';
        this._pilotLook = null;
        this._pilotLookKey = 'skin';
        this._heroPlanet = null;
        this._ppTimer = 0;
    }

    show(options) {
        this.isVisible = true;
        this.onComplete = options && options.onComplete;
        this.step = 'story';
        this._pendingName = '';
        this._pilotLook = null;
        this._pilotLookKey = 'skin';
        this._pendingFaction = (typeof factionManager !== 'undefined' && factionManager.getFactionIds)
            ? factionManager.getFactionIds()[0]
            : 'terran';
        this.createUI();
        if (typeof menuStateManager !== 'undefined') {
            menuStateManager.setScreen('onboarding');
        }
    }

    hide() {
        this.isVisible = false;
        clearTimeout(this._ppTimer);
        this._ppTimer = 0;
        this.stopHomePlanet();
        if (typeof profileSelectionManager !== 'undefined'
            && profileSelectionManager.overlay === this.overlay) {
            profileSelectionManager.overlay = null;
        }
        if (this._keyHandler) {
            document.removeEventListener('keydown', this._keyHandler);
            this._keyHandler = null;
        }
        if (this.overlay) {
            this.overlay.remove();
            this.overlay = null;
        }
    }

    finish() {
        const cb = this.onComplete;
        this.hide();
        if (typeof cb === 'function') cb();
    }

    getFactionIds() {
        if (typeof factionManager !== 'undefined' && factionManager.getFactionIds) {
            return factionManager.getFactionIds();
        }
        return ['terran', 'kronax', 'voidborn', 'pirate', 'machine'];
    }

    getFactionLabel(id) {
        if (typeof planetConfigManager !== 'undefined' && planetConfigManager.getFactionMeta) {
            const meta = planetConfigManager.getFactionMeta(id);
            if (meta && meta.label) return meta.label;
        }
        return String(id || '').toUpperCase();
    }

    getFactionColor(id) {
        if (typeof factionShipStyles !== 'undefined' && factionShipStyles.getFactionColor) {
            return factionShipStyles.getFactionColor(id);
        }
        return '#888888';
    }

    getFactionMeta(id) {
        if (typeof planetConfigManager !== 'undefined' && planetConfigManager.getFactionMeta) {
            return planetConfigManager.getFactionMeta(id);
        }
        return null;
    }

    getFactionEmblemHtml(id, size = 48) {
        if (typeof profileSelectionManager !== 'undefined' && profileSelectionManager.getFactionEmblemHtml) {
            return profileSelectionManager.getFactionEmblemHtml(id, size);
        }
        if (typeof iconRenderer === 'undefined' || typeof factionShipStyles === 'undefined') return '';
        const base = factionShipStyles.emblemCamelKey ? factionShipStyles.emblemCamelKey(id) : null;
        if (!base) return '';
        let key = base;
        if (typeof IconSprites !== 'undefined' && IconSprites[base + 'Hi'] && size >= 24) {
            key = base + (size >= 96 ? '@4x' : '@2x');
        } else if (typeof iconRenderer.detailKey === 'function') {
            key = iconRenderer.detailKey(base, size);
        }
        const style = factionShipStyles.getFactionStyle ? factionShipStyles.getFactionStyle(id) : null;
        return iconRenderer.imgHtml(key, size, 'profile-faction-emblem-img', style && style.accent, this.getFactionLabel(id));
    }

    factionSwatchesHtml() {
        return `
            <div class="profile-faction-picker onboarding-faction-picker">
                <div class="profile-faction-picker-label">CHOOSE YOUR FACTION</div>
                <div class="profile-faction-swatches">
                    ${this.getFactionIds().map((id) => `
                        <button type="button" class="profile-faction-swatch${id === this._pendingFaction ? ' selected' : ''}"
                            data-faction="${id}" title="${this.getFactionLabel(id)}"
                            style="--faction-color: ${this.getFactionColor(id)}">
                            <span class="profile-faction-swatch-emblem">${this.getFactionEmblemHtml(id, 48)}</span>
                            <span class="profile-faction-swatch-label">${this.getFactionLabel(id)}</span>
                        </button>
                    `).join('')}
                </div>
            </div>`;
    }

    factionPreviewHtml() {
        return `
            <div class="profile-faction-info-row onboarding-faction-preview">
                <div class="onboarding-faction-dossier onboarding-preview-card" role="note">
                    <div class="profile-faction-lore-text onboarding-dossier-lore"></div>
                    <div class="profile-faction-focus" data-faction-focus aria-label="Faction focus"></div>
                </div>
            </div>`;
    }

    stepIconHtml(key) {
        if (typeof ProfileSelectionManager !== 'undefined' && ProfileSelectionManager.stepIconHtml) {
            return ProfileSelectionManager.stepIconHtml(key);
        }
        const paths = {
            faction: 'M2 1h8v6H9v1H8v1H7v1H5V9H4V8H3V7H2zM5 3v3h2V3z',
            pilot: 'M4 1h4v1h1v3H8v1H4V5H3V2h1zM2 8h8v1h1v2H1V9h1z',
            name: 'M5 1h2v2h2v1h2v4h-2v1H7v2H5v-2H3V9H1V4h2V3h2zM5 5v2h2V5z'
        };
        return `<svg class="profile-stepper-icon" viewBox="0 0 12 12" width="40" height="40" shape-rendering="crispEdges" aria-hidden="true"><path fill="currentColor" fill-rule="evenodd" d="${paths[key] || paths.faction}"/></svg>`;
    }

    steps() {
        return [
            ['story', 'faction', 'FACTION'],
            ['pilot', 'pilot', 'PILOT'],
            ['name', 'name', 'CALLSIGN'],
            ['scrap', 'name', 'SHIP']
        ];
    }

    stepIndex(id) {
        const idx = this.steps().findIndex(([stepId]) => stepId === (id || this.step));
        return Math.max(0, idx);
    }

    stepperHtml() {
        const steps = this.steps();
        const idx = this.stepIndex();
        return `<ol class="profile-stepper onboarding-stepper" aria-label="Step ${idx + 1} of ${steps.length}">${steps.map(([id, icon, label], i) => `
            <li class="profile-stepper-step${i < idx ? ' is-done' : ''}${i === idx ? ' is-current' : ''}"${i === idx ? ' aria-current="step"' : ''}>
                ${i < idx
                    ? `<button type="button" class="profile-stepper-btn" data-step-go="${id}" title="Back to ${label}">`
                    : '<span class="profile-stepper-btn">'}
                    <span class="profile-stepper-dot">${this.stepIconHtml(icon)}</span>
                    <span class="profile-stepper-label">${label}</span>
                ${i < idx ? '</button>' : '</span>'}
            </li>`).join('')}</ol>`;
    }

    barHtml(primaryLabel, hint, showBack) {
        const back = showBack
            ? '<button class="action-button secondary" id="obBack">BACK</button>'
            : '';
        return `
            <div class="profile-selection-bar onboarding-bar">
                <div class="profile-selection-actions">
                    ${back}
                    <button class="action-button" id="obNext">${primaryLabel}</button>
                </div>
                <div class="profile-selection-instructions"><p>${hint}</p></div>
            </div>`;
    }

    ensurePilotLook() {
        if (typeof heroPortrait === 'undefined') return null;
        if (!this._pilotLook || this._pilotLook.faction !== this._pendingFaction) {
            this._pilotLook = heroPortrait.randomLook(this._pendingFaction);
            this._pilotLookKey = 'skin';
        }
        this._pilotLook = heroPortrait.normalize(this._pilotLook);
        const keys = heroPortrait.keysFor(this._pilotLook) || [];
        if (keys.indexOf(this._pilotLookKey) < 0) this._pilotLookKey = keys[0] || 'skin';
        return this._pilotLook;
    }

    pilotAccent() {
        return this.getFactionColor(this._pendingFaction);
    }

    pilotHtml() {
        const look = this.ensurePilotLook();
        if (!look || typeof heroPortrait === 'undefined') {
            return '<p class="onboarding-hint">PILOT LOOK UNAVAILABLE</p>';
        }
        const psm = typeof profileSelectionManager !== 'undefined' ? profileSelectionManager : null;
        if (psm && psm.renderPilotRowHtml) {
            psm.pendingFaction = this._pendingFaction;
            psm._startOpts = Object.assign({}, psm._startOpts || {}, {
                faction: this._pendingFaction,
                look: this._pilotLook,
                lookKey: this._pilotLookKey
            });
            return `<div class="profile-start-options onboarding-pilot-options">${psm.renderPilotRowHtml()}</div>`;
        }
        return `
            <div class="profile-start-options onboarding-pilot-options">
                <div class="profile-start-row" data-start-row="pilot">
                    <span class="profile-start-label">PILOT</span>
                    <div class="profile-pilot-card">
                        <div class="profile-pilot-side">
                            <div class="profile-pilot-portrait" id="psPortrait">${heroPortrait.html(look, this.pilotAccent())}</div>
                        </div>
                    </div>
                </div>
            </div>`;
    }

    createUI() {
        if (this.overlay) this.overlay.remove();
        if (this._keyHandler) {
            document.removeEventListener('keydown', this._keyHandler);
            this._keyHandler = null;
        }
        this.stopHomePlanet();

        this.overlay = document.createElement('div');
        this.overlay.className = 'profile-selection-overlay onboarding-overlay';

        let body = '';
        let bar = '';
        if (this.step === 'story') {
            body = `
                <div class="profile-selection-content onboarding-content onboarding-homeworld-site">
                    <div class="onboarding-homeworld-main onboarding-panel">
                        <h2 class="profile-selection-title">CHOOSE FACTION</h2>
                        ${this.factionSwatchesHtml()}
                        ${this.factionPreviewHtml()}
                    </div>
                    <aside class="onboarding-homeworld-stage onboarding-panel" aria-label="Faction homeworld">
                        <div class="onboarding-homeworld-label"></div>
                    </aside>
                </div>`;
            bar = this.barHtml('CONTINUE', '← → Faction | ENTER Continue', false);
        } else if (this.step === 'pilot') {
            body = `
                <div class="profile-selection-content onboarding-content onboarding-panel onboarding-pilot-panel profile-selection-name-mode is-name-step is-pilot-step">
                    <h2 class="profile-selection-title">CREATE YOUR PILOT</h2>
                    <p class="onboarding-hint">PICK A FACE · R RANDOMIZE</p>
                    ${this.pilotHtml()}
                </div>`;
            bar = this.barHtml('CONTINUE', '↑ ↓ Feature | ← → Change | R Randomize | ENTER Continue | ESC Back', true);
        } else if (this.step === 'name') {
            const psm = this.syncPilotToPsm();
            const crest = this.ensurePilotLook() && typeof heroPortrait !== 'undefined'
                ? `<span class="profile-name-crest onboarding-name-portrait" id="obNamePortrait">${heroPortrait.html(this._pilotLook, this.pilotAccent())}</span>`
                : `<span class="profile-name-crest">${this.getFactionEmblemHtml(this._pendingFaction, 48)}</span>`;
            const kitCol = (psm && psm.renderKitListHtml) ? psm.renderKitListHtml() : '';
            const loadout = (psm && psm.renderLoadoutHtml) ? psm.renderLoadoutHtml() : '';
            const kitInfo = (psm && psm.renderKitInfoHtml) ? psm.renderKitInfoHtml() : '';
            body = `
                <div class="profile-selection-content onboarding-content onboarding-panel onboarding-name-panel profile-selection-name-mode is-name-step">
                    <h2 class="profile-selection-title">PILOT CALLSIGN</h2>
                    <p class="onboarding-hint">ENTER YOUR NAME · PICK A START PROFILE</p>
                    <div class="profile-name-row onboarding-name-row">
                        ${crest}
                        <input type="text" class="profile-name-input" id="obNameInput" maxlength="16" placeholder="NAME" autocomplete="off" spellcheck="false"/>
                    </div>
                    <div class="profile-start-main onboarding-pilot-kit-main">
                        ${kitCol}
                        <div class="profile-faction-preview">
                            <div class="profile-faction-ship-wrap">
                                <canvas class="profile-faction-ship" width="320" height="224" aria-label="Starter hull preview"></canvas>
                            </div>
                            <div class="profile-kit-ship"></div>
                            <div class="profile-loadout">${loadout}</div>
                            <div class="profile-kit-info">${kitInfo}</div>
                        </div>
                    </div>
                </div>`;
            bar = this.barHtml('CONFIRM', '↑ ↓ Profile | ENTER Confirm | ESC Back', true);
        } else {
            body = `
                <div class="profile-selection-content onboarding-content onboarding-panel onboarding-ship-panel">
                    <h2 class="profile-selection-title">SHIP ASSEMBLY</h2>
                    <p class="onboarding-hint">YOUR STARTER HULL · OPEN THE HANGAR TO FIT MODULES</p>
                    <div class="onboarding-ship-wrap">
                        <canvas class="profile-faction-ship onboarding-ship-canvas" width="320" height="224" aria-label="Starter hull preview"></canvas>
                    </div>
                    <div class="profile-kit-ship"></div>
                    <p class="hs-status">READY FOR HANGAR</p>
                </div>`;
            bar = this.barHtml('OPEN HANGAR', 'ENTER Continue | ESC Back', true);
        }

        this.overlay.innerHTML = `${this.stepperHtml()}${body}${bar}`;

        document.body.appendChild(this.overlay);
        this.applyFactionSurface(this._pendingFaction);
        if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
            VFBgMouseParallax.refresh();
        }
        this.bindStep();
    }

    applyFactionSurface(id) {
        if (document.documentElement.getAttribute('data-pf') !== id) {
            document.documentElement.setAttribute('data-pf', id);
            if (typeof VFBgMouseParallax !== 'undefined' && VFBgMouseParallax.refresh) {
                VFBgMouseParallax.refresh();
            }
            if (window.vfRepaintBackdrops) window.vfRepaintBackdrops();
        }
        const color = this.getFactionColor(id);
        if (this.overlay) {
            this.overlay.style.setProperty('--faction-color', color);
            this.overlay.style.setProperty('--faction-accent', color);
        }
        const box = this.overlay && this.overlay.querySelector('.onboarding-content');
        if (box) {
            box.style.setProperty('--faction-color', color);
            box.style.setProperty('--faction-accent', color);
            box.dataset.faction = id;
        }
    }

    bindFactionPicker() {
        this.overlay.querySelectorAll('.profile-faction-swatch').forEach((button) => {
            button.addEventListener('click', () => {
                this.setFaction(button.dataset.faction);
            });
        });
    }

    setFaction(id) {
        if (!id || id === this._pendingFaction) {
            this.refreshFactionPreview();
            return;
        }
        this._pendingFaction = id;
        this._pilotLook = null;
        this.overlay.querySelectorAll('.profile-faction-swatch').forEach((item) => {
            item.classList.toggle('selected', item.dataset.faction === id);
        });
        this.applyFactionSurface(id);
        this.refreshFactionPreview();
        this.startHomePlanet();
    }

    syncPilotToPsm() {
        const psm = typeof profileSelectionManager !== 'undefined' ? profileSelectionManager : null;
        if (!psm) return null;
        this.ensurePilotLook();
        // Treat as create-wizard so kit/inventory + ship preview use start-hull paths.
        psm.mode = 'create';
        psm.pendingFaction = this._pendingFaction;
        psm._startOpts = Object.assign({}, psm._startOpts || {}, {
            faction: this._pendingFaction,
            look: this._pilotLook,
            lookKey: this._pilotLookKey
        });
        if (!psm._startOpts.areas) psm._startOpts.areas = {};
        psm.overlay = this.overlay;
        return psm;
    }

    refreshPilotUi() {
        const psm = this.syncPilotToPsm();
        if (psm && psm.refreshPilotRow) {
            psm.refreshPilotRow();
            this._pilotLook = psm._startOpts && psm._startOpts.look
                ? Object.assign({}, psm._startOpts.look)
                : this._pilotLook;
            this._pilotLookKey = (psm._startOpts && psm._startOpts.lookKey) || this._pilotLookKey;
            return;
        }
        const box = this.overlay && this.overlay.querySelector('#psPortrait');
        if (box && this._pilotLook && typeof heroPortrait !== 'undefined') {
            box.innerHTML = heroPortrait.html(this._pilotLook, this.pilotAccent());
        }
    }

    bindPilotControls() {
        const psm = this.syncPilotToPsm();
        if (!this.overlay) return;
        this.overlay.querySelectorAll('.pp-ctl').forEach((el) => {
            const k = el.getAttribute('data-pp-key');
            el.addEventListener('click', (e) => {
                if (e.target.closest('[data-pp-slider]')) return;
                this._pilotLookKey = k;
                if (psm && psm._startOpts) psm._startOpts.lookKey = k;
                this.refreshPilotUi();
            });
            const sl = el.querySelector('.pp-slider');
            if (!sl) return;
            sl.addEventListener('change', () => {
                clearTimeout(this._ppTimer);
                this._ppTimer = 0;
                this.refreshPilotUi();
            });
            sl.addEventListener('input', () => {
                this._pilotLookKey = k;
                this._pilotLook = Object.assign({}, this.ensurePilotLook(), { [k]: Number(sl.value) });
                if (psm && psm._startOpts) {
                    psm._startOpts.lookKey = k;
                    psm._startOpts.look = this._pilotLook;
                }
                const val = el.querySelector('.pp-val');
                if (val && typeof heroPortrait !== 'undefined') {
                    val.textContent = heroPortrait.valueName(k, this._pilotLook[k], this._pilotLook);
                }
                if (this._ppTimer) return;
                this._ppTimer = setTimeout(() => {
                    this._ppTimer = 0;
                    this.refreshPilotUi();
                }, 90);
            });
        });
        this.overlay.querySelectorAll('[data-pp-pick]').forEach((btn) => {
            btn.addEventListener('click', () => {
                this._pilotLookKey = 'v';
                this._pilotLook = Object.assign({}, this.ensurePilotLook(), {
                    v: Number(btn.getAttribute('data-pp-pick'))
                });
                if (psm && psm._startOpts) {
                    psm._startOpts.lookKey = 'v';
                    psm._startOpts.look = this._pilotLook;
                }
                this.refreshPilotUi();
            });
        });
        if (psm && psm.ensurePilotPicksFit) psm.ensurePilotPicksFit();
    }

    goTo(step) {
        const allowed = this.steps().map(([id]) => id);
        if (allowed.indexOf(step) < 0) return;
        if (this.stepIndex(step) > this.stepIndex()) return;
        this.step = step;
        this.createUI();
    }

    goBack() {
        const idx = this.stepIndex();
        if (idx <= 0) return;
        this.step = this.steps()[idx - 1][0];
        this.createUI();
    }

    refreshFactionPreview() {
        if (!this.overlay || this.step !== 'story') return;
        const id = this._pendingFaction;
        const meta = this.getFactionMeta(id);
        const lead = (meta && meta.lore) || '';
        // Lore lives under the faction title on the right stage — not in the left dossier.
        const loreEl = this.overlay.querySelector('.profile-faction-lore-text');
        if (loreEl) loreEl.innerHTML = '';
        const focusEl = this.overlay.querySelector('[data-faction-focus]');
        if (focusEl && typeof ProfileSelectionManager !== 'undefined' && ProfileSelectionManager.prototype.buildFactionFocusHtml) {
            focusEl.innerHTML = ProfileSelectionManager.prototype.buildFactionFocusHtml.call(
                ProfileSelectionManager.prototype, id, meta);
        }
        const homeLabel = this.overlay.querySelector('.onboarding-homeworld-label');
        if (homeLabel) {
            const galaxy = String((meta && meta.homeGalaxy) || '').replace(/_/g, ' ').toUpperCase();
            const name = this.getFactionLabel(id);
            const sub = galaxy ? `HOMEWORLD · ${galaxy}` : 'HOMEWORLD';
            const lore = lead || (name + ' fleets hold this homeworld.');
            // Crest + name on the right stage; lore directly under the title.
            homeLabel.innerHTML =
                `<span class="onboarding-homeworld-crest">${this.getFactionEmblemHtml(id, 160)}</span>` +
                `<span class="onboarding-homeworld-title">` +
                `<b class="onboarding-homeworld-name">${name}</b>` +
                `<small class="onboarding-homeworld-sub">${sub}</small>` +
                `<p class="onboarding-homeworld-lore">${lore}</p>` +
                `</span>`;
        }
        if (this._heroPlanet) this._heroPlanet.setFaction(id);
    }

    stopHomePlanet() {
        if (this._heroPlanet && this._heroPlanet.unmount) {
            this._heroPlanet.unmount();
        }
        this._heroPlanet = null;
    }

    startHomePlanet() {
        if (!this.overlay || this.step !== 'story') return;
        const stage = this.overlay.querySelector('.onboarding-homeworld-stage');
        if (!stage) return;
        if (typeof HeroPlanetBackdrop === 'undefined') {
            // Profiles chunk may still be loading — retry briefly.
            clearTimeout(this._planetRetry);
            this._planetRetry = setTimeout(() => {
                if (this.overlay && this.step === 'story') this.startHomePlanet();
            }, 200);
            return;
        }
        if (!this._heroPlanet) this._heroPlanet = new HeroPlanetBackdrop();
        if (this._heroPlanet.setLayout) this._heroPlanet.setLayout('stage');
        this._heroPlanet.setFaction(this._pendingFaction);
        this._heroPlanet.mount(stage);
        stage.classList.add('has-hero-planet');
    }

    bindStep() {
        const next = this.overlay.querySelector('#obNext');
        if (next) next.addEventListener('click', () => this.advance());
        const back = this.overlay.querySelector('#obBack');
        if (back) back.addEventListener('click', () => this.goBack());
        this.overlay.querySelectorAll('[data-step-go]').forEach((btn) => {
            btn.addEventListener('click', () => this.goTo(btn.getAttribute('data-step-go')));
        });

        if (this.step === 'story') {
            this.bindFactionPicker();
            this.startHomePlanet();
            // Wait a frame so the preview canvas has layout before the first paint.
            requestAnimationFrame(() => {
                if (!this.overlay || this.step !== 'story') return;
                this.refreshFactionPreview();
                this.startHomePlanet();
                requestAnimationFrame(() => {
                    if (this.overlay && this.step === 'story') this.refreshFactionPreview();
                });
            });
        }

        if (this.step === 'pilot') {
            this.bindPilotControls();
        }

        if (this.step === 'name') {
            const input = this.overlay.querySelector('#obNameInput');
            if (input) {
                input.focus();
                if (this._pendingName) input.value = this._pendingName;
                const meta = this.getFactionMeta(this._pendingFaction);
                if (meta && meta.hero && meta.hero.name && !input.value) {
                    input.placeholder = meta.hero.name.slice(0, 16);
                }
            }
            this.bindPilotKit();
        }

        if (this.step === 'scrap') {
            this.bindShipPreview();
        }

        this._keyHandler = (e) => {
            if (!this.isVisible) return;
            // Start screen is hidden during onboarding and the editors bundle (global
            // Shift+C) may not be loaded yet — handle DevMode here like the profile overlay.
            if (e.shiftKey && (e.key === 'c' || e.key === 'C')) {
                const tag = e.target && e.target.tagName;
                if (tag !== 'INPUT' && tag !== 'TEXTAREA' && typeof startScreenManager !== 'undefined') {
                    if (e.repeat) return;
                    e.preventDefault();
                    startScreenManager.toggleDevMode();
                }
                return;
            }
            if (e.key === 'Escape') {
                e.preventDefault();
                if (this.stepIndex() > 0) this.goBack();
                return;
            }
            if (this.step === 'story' && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) {
                e.preventDefault();
                const ids = this.getFactionIds();
                const i = Math.max(0, ids.indexOf(this._pendingFaction));
                const nextId = ids[(i + (e.key === 'ArrowRight' ? 1 : ids.length - 1)) % ids.length];
                this.setFaction(nextId);
                return;
            }
            if (this.step === 'pilot') {
                const psm = this.syncPilotToPsm();
                if ((e.key === 'r' || e.key === 'R') && !(e.target && e.target.tagName === 'INPUT')) {
                    e.preventDefault();
                    if (psm && psm.randomizePilotLook) {
                        psm.randomizePilotLook();
                        this._pilotLook = psm._startOpts && psm._startOpts.look
                            ? Object.assign({}, psm._startOpts.look)
                            : this._pilotLook;
                    } else if (typeof heroPortrait !== 'undefined') {
                        this._pilotLook = heroPortrait.randomLook(this._pendingFaction);
                        this.refreshPilotUi();
                    }
                    return;
                }
                if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
                    e.preventDefault();
                    const d = e.key === 'ArrowRight' ? 1 : -1;
                    if (psm && psm.stepPilotLook) {
                        psm.stepPilotLook(this._pilotLookKey, d);
                        this._pilotLook = psm._startOpts && psm._startOpts.look
                            ? Object.assign({}, psm._startOpts.look)
                            : this._pilotLook;
                        this._pilotLookKey = (psm._startOpts && psm._startOpts.lookKey) || this._pilotLookKey;
                    } else if (typeof heroPortrait !== 'undefined') {
                        this._pilotLook = heroPortrait.cycle(this.ensurePilotLook(), this._pilotLookKey, d);
                        this.refreshPilotUi();
                    }
                    return;
                }
                if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
                    e.preventDefault();
                    const keys = (typeof heroPortrait !== 'undefined' && heroPortrait.keysFor)
                        ? heroPortrait.keysFor(this.ensurePilotLook())
                        : [];
                    if (!keys.length) return;
                    const i = Math.max(0, keys.indexOf(this._pilotLookKey));
                    this._pilotLookKey = keys[(i + (e.key === 'ArrowDown' ? 1 : keys.length - 1)) % keys.length];
                    if (psm && psm._startOpts) psm._startOpts.lookKey = this._pilotLookKey;
                    this.refreshPilotUi();
                    return;
                }
            }
            if (this.step === 'name' && e.target && e.target.id === 'obNameInput') {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    this.advance();
                }
                return;
            }
            if (this.step === 'name' && (e.key === 'ArrowUp' || e.key === 'ArrowDown')
                && !(e.target && e.target.id === 'obNameInput')) {
                e.preventDefault();
                const chips = Array.from(this.overlay.querySelectorAll('[data-start-opt="kit"]'));
                if (!chips.length) return;
                const cur = chips.findIndex((b) => b.classList.contains('selected'));
                const next = chips[(Math.max(0, cur) + (e.key === 'ArrowDown' ? 1 : chips.length - 1)) % chips.length];
                if (next) next.click();
                return;
            }
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                this.advance();
            }
        };
        document.addEventListener('keydown', this._keyHandler);
    }

    advance() {
        if (this.step === 'story') {
            this.step = 'pilot';
            this.createUI();
            return;
        }
        if (this.step === 'pilot') {
            this.ensurePilotLook();
            this.step = 'name';
            this.createUI();
            return;
        }
        if (this.step === 'name') {
            const input = this.overlay.querySelector('#obNameInput');
            const name = input ? input.value : '';
            if (typeof profileManager === 'undefined') return;
            let p = profileManager.getActiveProfile && profileManager.getActiveProfile();
            const already = p && this._pendingName && p.name === String(name || '').trim().toUpperCase().slice(0, 16)
                && p.faction === this._pendingFaction;
            if (!already) {
                p = profileManager.create(name, this._pendingFaction);
            }
            if (!p) {
                if (input) {
                    input.classList.add('nav-focused');
                    input.focus();
                }
                return;
            }
            profileManager.setActive(p.id);
            if (this._pilotLook) {
                p.portrait = Object.assign({}, this._pilotLook);
            }
            const psm = this.syncPilotToPsm();
            if (psm && psm.applyStartOptions) {
                try { psm.applyStartOptions(p); } catch (e) { /* continue */ }
            }
            if (profileManager.save) profileManager.save();
            this._pendingName = p.name;
            this.step = 'scrap';
            this.createUI();
            return;
        }
        this.hide();
        if (typeof homeStationUI !== 'undefined') {
            homeStationUI.show({
                tab: 'hangar',
                onClose: this.onComplete
            });
            return;
        }
        if (typeof this.onComplete === 'function') this.onComplete();
    }

    /** START PROFILE + inventory under the callsign (pilot) step. */
    bindPilotKit() {
        const psm = this.syncPilotToPsm();
        if (!psm || !this.overlay) return;
        if (!psm._startOpts) psm._startOpts = {};
        psm._startOpts.faction = this._pendingFaction;
        psm.pendingFaction = this._pendingFaction;
        if (psm.currentKit) psm.currentKit();
        this.overlay.querySelectorAll('[data-start-opt="kit"]').forEach((btn) => {
            btn.addEventListener('click', () => {
                psm._startOpts.kit = btn.getAttribute('data-value');
                psm._startOpts.ship = psm.kitShipId ? psm.kitShipId(psm._startOpts.kit) : psm._startOpts.ship;
                psm._startOpts.storyPathId = null;
                this.overlay.querySelectorAll('[data-start-opt="kit"]').forEach((b) => {
                    const on = b === btn;
                    b.classList.toggle('selected', on);
                    b.setAttribute('aria-pressed', on ? 'true' : 'false');
                });
                const loadout = this.overlay.querySelector('.profile-loadout');
                if (loadout && psm.renderLoadoutHtml) loadout.innerHTML = psm.renderLoadoutHtml();
                const kitInfo = this.overlay.querySelector('.profile-kit-info');
                if (kitInfo && psm.renderKitInfoHtml) kitInfo.innerHTML = psm.renderKitInfoHtml();
                if (psm.renderFactionShipPreview) psm.renderFactionShipPreview(this._pendingFaction);
                if (psm.renderKitShipInfo) psm.renderKitShipInfo();
            });
        });
        if (psm.renderFactionShipPreview) psm.renderFactionShipPreview(this._pendingFaction);
        if (psm.renderKitShipInfo) psm.renderKitShipInfo();
    }

    /** Ship step: preview the kit hull already chosen with the pilot. */
    bindShipPreview() {
        const psm = this.syncPilotToPsm();
        if (!psm || !this.overlay) return;
        if (psm.renderFactionShipPreview) psm.renderFactionShipPreview(this._pendingFaction);
        if (psm.renderKitShipInfo) psm.renderKitShipInfo();
    }
}

