/* --- js/ui/component-tree.js?v=sdrop-2 --- */
// Component Tree View for Hangar UI
var ComponentTree = class ComponentTree {
    constructor() {
        this.expandedDepth = 0;
        this.expandedNodes = new Set();
        this.shipId = null;
        this.storageKey = 'vf_component_tree_expanded_v1';
    }

    setShip(shipId) {
        const nextShipId = String(shipId || '');
        if (this.shipId === nextShipId) return;

        this.persistExpandedNodes();
        this.shipId = nextShipId;
        const stored = localStorage.getItem(`${this.storageKey}:${encodeURIComponent(nextShipId)}`);
        this.expandedNodes = new Set(stored ? stored.split('|').filter(Boolean) : []);
    }

    setNodeExpanded(nodeId, isExpanded) {
        if (!nodeId) return;
        if (isExpanded) {
            this.expandedNodes.add(nodeId);
        } else {
            this.expandedNodes.delete(nodeId);
        }
        this.persistExpandedNodes();
    }

    persistExpandedNodes() {
        if (this.shipId === null) return;
        localStorage.setItem(
            `${this.storageKey}:${encodeURIComponent(this.shipId)}`,
            [...this.expandedNodes].join('|')
        );
    }

    /**
     * Render a complete component tree with slots
     * @param {Object} hangarSlots - Slot configuration from shipLoadoutManager
     * @param {Object} loadout - Current ship loadout
     * @param {Object} inventory - Available components
     * @returns {string} HTML for the tree
     */
    render(hangarSlots, loadout, inventory, skinOptionsForSlot, styleOptionsForArea) {
        if (!hangarSlots || !hangarSlots.slots) return '<div class="hs-tree-empty">No components</div>';

        // With wing symmetry on, both wings share one style, so they show as
        // a single WINGS branch holding the slots of both sides.
        const wingConfig = styleOptionsForArea ? styleOptionsForArea('wingLeft') : null;
        const symmetric = !!(wingConfig && wingConfig.symmetric);
        const tree = {};
        const areas = symmetric
            ? ['front', 'center', 'wings', 'back']
            : ['front', 'center', 'wingLeft', 'wingRight', 'back'];
        areas.forEach((area) => {
            tree[area] = (hangarSlots.slots || []).filter((slot) => slot && (area === 'wings'
                ? slot.area === 'wingLeft' || slot.area === 'wingRight'
                : slot.area === area));
        });

        return `<div class="hs-tree-root">${
            areas
                .map((area) => this.renderBranch(
                    area,
                    tree[area],
                    loadout,
                    inventory,
                    skinOptionsForSlot,
                    styleOptionsForArea
                ))
                .join('')
        }</div>`;
    }

    /**
     * Render a ship-area branch (e.g., "LEFT WING", "AFT").
     */
    renderBranch(area, slots, loadout, inventory, skinOptionsForSlot, styleOptionsForArea) {
        const label = this.labelForArea(area);
        const nodeId = `hs-tree-area-${area}`;
        const isExpanded = this.expandedNodes.has(nodeId);
        const styleConfig = styleOptionsForArea
            ? styleOptionsForArea(area === 'wings' ? 'wingLeft' : area)
            : { styles: [] };
        const styles = Array.isArray(styleConfig) ? styleConfig : styleConfig.styles;
        const styleControls = styles.length > 1
            ? `<div class="hs-tree-area-style">
                    <span class="hs-tree-skin-label">HULL STYLE</span>
                    ${this.renderStyleCarousel(styles.map((style) => ({
                        active: style.active,
                        locked: style.locked,
                        label: style.label,
                        attrs: `data-tree-area-style="${area}" data-segment-id="${style.segmentId}" data-style-index="${style.index}"`,
                        thumb: `data-thumb="area" data-thumb-area="${area === 'wings' ? 'wingRight' : area}" data-thumb-index="${style.index}"`
                    })))}
                </div>`
            : '';
        const symmetryControl = styleConfig.isWing
            ? `<button type="button" class="hs-tree-wing-symmetry${styleConfig.symmetric ? ' is-active' : ''}" data-tree-wing-symmetry="${styleConfig.symmetric ? 'on' : 'off'}">SYMMETRY ${styleConfig.symmetric ? 'ON' : 'OFF'}</button>`
            : '';
        const toggleable = ['front', 'back', 'wings'].indexOf(area) !== -1;
        const toggleArea = area === 'wings' ? 'wing' : area;
        const areaToggle = toggleable && typeof shipLoadoutManager !== 'undefined'
            ? (() => {
                const on = shipLoadoutManager.isAreaEnabled(this.shipId, toggleArea);
                return `<label class="hs-tree-area-toggle" title="${on ? 'Switch off' : 'Switch on'}" onclick="event.stopPropagation()"><input type="checkbox" data-area-toggle="${this.shipId}|${toggleArea}"${on ? ' checked' : ''} aria-label="${label} on/off"><span>${on ? 'ON' : 'OFF'}</span></label>`;
            })()
            : '';

        return `
            <details class="hs-tree-branch" ${isExpanded ? 'open' : ''} id="${nodeId}">
                <summary class="hs-tree-branch-label">
                    <span class="hs-tree-toggle">▶</span>
                    <span class="hs-tree-icon">${this.iconForArea(area)}</span>
                    <span class="hs-tree-text">${label} ${slots.length}</span>
                    ${areaToggle}
                </summary>
                <div class="hs-tree-items">
                    ${symmetryControl}
                    ${styleControls}
                    ${slots.length
                        ? slots.map((slot) => this.renderSlot(slot.kind, slot, loadout, inventory, skinOptionsForSlot)).join('')
                        : '<div class="hs-tree-empty">NO COMPONENTS</div>'}
                </div>
            </details>
        `;
    }

    /**
     * Style picker as a dropdown: the closed control shows the active style
     * as a large thumbnail; opening it lists every unlocked style with its
     * thumbnail and name. Options carry the same data attributes as before,
     * so the existing click handlers apply the choice unchanged (the tree is
     * rebuilt afterwards, which closes the dropdown). Thumbnails are
     * canvases painted after render (see renderStyleThumbs).
     */
    renderStyleCarousel(allOptions) {
        // Only unlocked styles are offered; buying more happens in the shop.
        const options = allOptions.filter((opt) => !opt.locked);
        if (!options.length) return '';
        const activeIndex = Math.max(0, options.findIndex((opt) => opt.active));
        const active = options[activeIndex];
        return `<details class="hs-style-dropdown">
                <summary class="hs-style-dropdown-current" title="${active.label}">
                    <span class="hs-style-dropdown-thumb"><canvas width="96" height="72" ${active.thumb}></canvas></span>
                    <span class="hs-style-dropdown-text">
                        <strong>${active.label}</strong>
                        <small>${activeIndex + 1}/${options.length}</small>
                    </span>
                    <span class="hs-style-dropdown-caret" aria-hidden="true">▾</span>
                </summary>
                <div class="hs-style-dropdown-list" role="listbox">
                    ${options.map((opt) => `<button type="button" class="hs-style-option${opt.active ? ' is-active' : ''}" ${opt.attrs} role="option" aria-selected="${!!opt.active}" title="${opt.label}">
                        <span class="hs-style-dropdown-thumb"><canvas width="96" height="72" ${opt.thumb}></canvas></span>
                        <span class="hs-style-option-label">${opt.label}</span>
                    </button>`).join('')}
                </div>
            </details>`;
    }

    /**
     * Render a single slot with dropdown for equipping
     */
    renderSlot(kind, slot, loadout, inventory, skinOptionsForSlot) {
        const slotIndex = slot.index;
        const slotId = `hs-tree-slot-${kind}-${slotIndex}`;
        const equipped = this.getEquippedModule(loadout, kind, slotIndex);
        const isExpanded = this.expandedNodes.has(slotId);
        const inventoryKey = this.loadoutKeyForKind(kind);

        const availableComponents = (inventory && inventory[inventoryKey]) || [];
        const options = availableComponents.map((comp) => {
            const selected = equipped === comp ? ' selected' : '';
            return `<option value="${comp}"${selected}>${comp}</option>`;
        }).join('');
        const skins = equipped && skinOptionsForSlot
            ? skinOptionsForSlot(kind, slot, equipped)
            : [];
        const skinControls = skins.length > 1
            ? `<div class="hs-tree-skin-controls">
                    <span class="hs-tree-skin-label">STYLE</span>
                    ${this.renderStyleCarousel(skins.map((skin) => ({
                        active: skin.active,
                        locked: skin.locked,
                        label: skin.label,
                        attrs: `data-tree-skin-set="${kind}" data-slot-index="${slotIndex}" data-mod-id="${equipped}" data-mod-face="${slot.face || ''}" data-skin-id="${skin.id}"`,
                        thumb: `data-thumb="skin" data-thumb-kind="${kind}" data-thumb-module="${equipped}" data-thumb-skin="${skin.id}" data-thumb-face="${slot.face || ''}"`
                    })))}
                </div>`
            : '';

        return `
            <details class="hs-tree-item" ${isExpanded ? 'open' : ''} id="${slotId}">
                <summary class="hs-tree-item-label">
                    <span class="hs-tree-toggle">▶</span>
                    <span class="hs-tree-slot-name">${slot.label || `SLOT ${slotIndex + 1}`}</span>
                    ${equipped ? `<span class="hs-tree-equipped">${equipped}</span>` : '<span class="hs-tree-empty-slot">—</span>'}
                </summary>
                <div class="hs-tree-slot-content">
                    <select class="hs-tree-slot-select" data-slot-kind="${kind}" data-slot-index="${slotIndex}">
                        <option value="">UNEQUIP</option>
                        ${options}
                    </select>
                    ${skinControls}
                </div>
            </details>
        `;
    }

    /**
     * Get the currently equipped module for a slot
     */
    getEquippedModule(loadout, kind, slotIndex) {
        const key = this.loadoutKeyForKind(kind);
        if (!loadout || !loadout[key]) return null;
        const equipped = loadout[key][slotIndex];
        return equipped || null;
    }

    loadoutKeyForKind(kind) {
        return {
            weapon: 'weapons',
            defense: 'defenses',
            ability: 'abilities',
            energy: 'energy'
        }[kind] || kind;
    }

    /**
     * Get label for a structural ship area.
     */
    labelForArea(area) {
        return {
            front: 'NOSE',
            center: 'CORE',
            wingLeft: 'LEFT WING',
            wingRight: 'RIGHT WING',
            wings: 'WINGS',
            back: 'AFT'
        }[area] || area.toUpperCase();
    }

    /**
     * Get icon for a structural ship area.
     */
    iconForArea(area) {
        // Little pixel pictograms of the ship part (8×8), so an area reads
        // as a hull piece and not as another expand arrow.
        const svg = (d) => `<svg class="hs-area-glyph" viewBox="0 0 8 8" width="20" height="20" shape-rendering="crispEdges" aria-hidden="true"><path fill="currentColor" d="${d}"/></svg>`;
        const icons = {
            front: svg('M3 0h2v1h1v2h1v3H1V3h1V1h1zM3 6h2v2H3z'),
            center: svg('M2 0h4v1h1v6H6v1H2V7H1V1h1zM3 2v3h2V2z'),
            wingLeft: svg('M0 3h2v1h1v1h2v2H3V6H2V5H1V4H0zM5 1h2v6H5z'),
            wingRight: svg('M6 3h2v1H7v1H6v1H5v1H3V5h2V4h1zM1 1h2v6H1z'),
            wings: svg('M0 2h2v4H0zM6 2h2v4H6zM2 3h4v2H2z'),
            back: svg('M1 0h6v4H6v1H5v1H3V5H2V4H1zM2 6h1v2H2zM5 6h1v2H5z')
        };
        return icons[area] || icons.center;
    }

    /**
     * Set the expand depth from slider value
     */
    setExpandDepth(depth) {
        this.expandedDepth = Math.max(0, Math.min(3, parseInt(depth, 10)));
        this.updateAllDetails();
    }

    /**
     * Update all details elements based on current depth
     */
    updateAllDetails() {
        const roots = document.querySelectorAll('.hs-component-tree[data-ship-id]');
        if (!roots.length) return;

        roots.forEach((root) => {
            // Update branches (depth 1)
            root.querySelectorAll('.hs-tree-branch').forEach((branch) => {
                if (this.expandedDepth >= 1) {
                    branch.setAttribute('open', '');
                } else {
                    branch.removeAttribute('open');
                }
            });

            // Update items/slots (depth 2)
            root.querySelectorAll('.hs-tree-item').forEach((item) => {
                if (this.expandedDepth >= 2) {
                    item.setAttribute('open', '');
                } else {
                    item.removeAttribute('open');
                }
            });
        });
    }
}

// Create global instance
window.componentTree = new ComponentTree();


/* --- js/ui/menu-order.js?v=names-3 --- */
"use strict";

// Order of the Home Station tab rows. Reorder freely; moving an id between
// the lists moves it between the rows ('station' always stays in main).
//   main: the normal tab row
//   esc:  the row shown after pressing ESC
// Shift+C in the station (dev mode) lets you drag tabs to reorder them;
// that order is saved in the browser and overrides the lists below.
// '|' is a cluster divider (a line between tab groups) and can be moved like a tab.
// Available ids: play, travel, explorations, upgrade, hangar, components,
// missions, craft, shop, factions, profiles, settings, audio, assets,
// portraits, credits
// (Music Editor lives on the bezel AUDIO remote when widened.)
var MENU_ORDER = {
    main: [
        'station',
        'play',
        'travel',
        'explorations',
        '|',
        'upgrade',
        'hangar',
        'missions',
        'craft',
        '|',
        'shop'
    ],
    esc: [
        'settings',
        'audio',
        'layout',
        'assets',
        'components',
        'portraits',
        'credits'
    ]
};

// Built-in menu row order (before any saved order replaces it), for RESET.
var MENU_ORDER_DEFAULT_ESC = MENU_ORDER.esc.slice();

// Coarse navigation areas of the top bar. Each area is one big button; the
// tabs of the active area show up next to it as small icon tabs.
// The first tab of an area is where a click on the area lands first.
var MENU_AREAS = [
    { id: 'station', label: 'STATION', icon: 'hsStation', tabs: ['station'], defaultTab: 'station' },
    // defaultTab: where a click on the area lands (PLAY / the galaxy map is
    // only opened on purpose).
    { id: 'hangar', label: 'HANGAR', icon: 'hsHangar', tabs: ['hangar', 'upgrade', 'missions', 'craft', 'shop'], defaultTab: 'upgrade' },
    { id: 'factions', label: 'FACTIONS', icon: 'menuPeoples', tabs: ['factions', 'ffleet', 'ftrade', 'fcontracts'] },
    { id: 'explore', label: 'WIKI', icon: 'hsExplore', tabs: ['travel', 'explorations'], defaultTab: 'explorations' }
];

var MENU_ORDER_STORAGE_KEY = 'vf.menuOrder';

(function loadSavedMenuOrder() {
    try {
        const saved = JSON.parse(localStorage.getItem(MENU_ORDER_STORAGE_KEY) || 'null');
        if (!saved || !Array.isArray(saved.main) || !Array.isArray(saved.esc)) return;
        // Ids added to the defaults later still show up at the end of their row.
        const known = saved.main.concat(saved.esc);
        const isNew = (id) => id !== '|' && known.indexOf(id) === -1;
        // The mission board belongs right before CRAFT, not at the row's end.
        const savedMain = saved.main.slice();
        if (known.indexOf('missions') === -1 && savedMain.indexOf('craft') !== -1) {
            savedMain.splice(savedMain.indexOf('craft'), 0, 'missions');
        }
        const main = savedMain.concat(MENU_ORDER.main.filter((id) => isNew(id) && id !== 'station' && savedMain.indexOf(id) === -1));
        // Home Station became movable later: older saves get it back at the front.
        if (main.indexOf('station') === -1) main.unshift('station');
        // Orders saved before dividers existed: put the default dividers back
        // after the same tab they follow in the defaults.
        if (main.indexOf('|') === -1) {
            MENU_ORDER.main.forEach((id, i) => {
                if (id !== '|' || i === 0) return;
                const at = main.indexOf(MENU_ORDER.main[i - 1]);
                if (at !== -1) main.splice(at + 1, 0, '|');
            });
        }
        MENU_ORDER.main = main;
        const esc = saved.esc.slice();
        // PORTRAITS (dev mode) belongs right before CREDITS, not at the row's end.
        if (known.indexOf('portraits') === -1 && esc.indexOf('credits') !== -1) esc.splice(esc.indexOf('credits'), 0, 'portraits');
        // MUSIC editor moved to the bezel remote — drop stale ESC-menu entries.
        // AUDIO left SETTINGS: place it right after SETTINGS (or before LAYOUT).
        if (known.indexOf('audio') === -1) {
            if (esc.indexOf('settings') !== -1) esc.splice(esc.indexOf('settings') + 1, 0, 'audio');
            else if (esc.indexOf('layout') !== -1) esc.splice(esc.indexOf('layout'), 0, 'audio');
            else esc.unshift('audio');
        }
        MENU_ORDER.esc = esc.concat(MENU_ORDER.esc.filter((id) => isNew(id) && esc.indexOf(id) === -1))
            .filter((id) => id !== 'station' && id !== 'music');
    } catch (e) { /* ignore */ }
})();

// ---- Top bar order (dev mode: drag the area buttons and '|' dividers) ----
// A list of area ids, 'profiles', 'menu' and '|' dividers; normalised on every read so
// areas added or removed in the LAYOUT editor always appear exactly once.
var MENU_AREA_ORDER_KEY = 'vf.areaOrder';

function getAreaOrder() {
    const ids = MENU_AREAS.map((a) => a.id).concat(['profiles', 'menu']);
    let saved = null;
    try { saved = JSON.parse(localStorage.getItem(MENU_AREA_ORDER_KEY) || 'null'); } catch (e) { /* ignore */ }
    const out = [];
    (Array.isArray(saved) ? saved : []).forEach((id) => {
        if (id === '|') out.push('|');
        else if (ids.indexOf(id) !== -1 && out.indexOf(id) === -1) out.push(id);
    });
    ids.forEach((id) => {
        if (out.indexOf(id) !== -1) return;
        if (out.length && out[out.length - 1] !== '|') out.push('|');
        out.push(id);
    });
    return out;
}

function saveAreaOrder(list) {
    try { localStorage.setItem(MENU_AREA_ORDER_KEY, JSON.stringify(list)); } catch (e) { /* ignore */ }
}

function saveMenuOrder() {
    try {
        localStorage.setItem(MENU_ORDER_STORAGE_KEY, JSON.stringify(MENU_ORDER));
    } catch (e) { /* ignore */ }
}

// ---- Player-editable area layout (Menu → LAYOUT) ------------------------
// Saved as [{ id, tabs, defaultTab }] in the order of the areas; labels and
// icons always come from the defaults above. Tabs the save doesn't know
// (added later) go back into their default area.
var MENU_AREAS_STORAGE_KEY = 'vf.menuAreas';
var MENU_AREAS_DEFAULTS = MENU_AREAS.map((a) => Object.assign({}, a, { tabs: a.tabs.slice() }));

function applyMenuAreasLayout(layout) {
    if (!Array.isArray(layout) || !layout.length) return false;
    const byId = {};
    MENU_AREAS_DEFAULTS.forEach((a) => { byId[a.id] = a; });
    // Station tabs that may live in an area (COMPONENTS defaults to the menu).
    const allTabs = [].concat(...MENU_AREAS_DEFAULTS.map((a) => a.tabs)).concat(['components']);
    // Tabs moved into the menu row stay there (not re-added to an area).
    const seen = {};
    (MENU_ORDER.esc || []).forEach((t) => { seen[t] = true; });
    const next = [];
    layout.forEach((entry) => {
        const base = entry && byId[entry.id];
        if (!base || next.some((a) => a.id === base.id)) return;
        const tabs = (Array.isArray(entry.tabs) ? entry.tabs : []).filter((t) => allTabs.indexOf(t) !== -1 && !seen[t]);
        tabs.forEach((t) => { seen[t] = true; });
        next.push(Object.assign({}, base, { tabs: tabs, defaultTab: entry.defaultTab || base.defaultTab }));
    });
    MENU_AREAS_DEFAULTS.forEach((base) => {
        let area = next.find((a) => a.id === base.id);
        if (!area) { area = Object.assign({}, base, { tabs: [] }); next.push(area); }
        base.tabs.forEach((t) => { if (!seen[t]) { seen[t] = true; area.tabs.push(t); } });
    });
    next.forEach((a) => { if (a.tabs.indexOf(a.defaultTab) === -1) a.defaultTab = a.tabs[0]; });
    MENU_AREAS.length = 0;
    next.forEach((a) => MENU_AREAS.push(a));
    return true;
}

function saveMenuAreas() {
    try {
        localStorage.setItem(MENU_AREAS_STORAGE_KEY, JSON.stringify(
            MENU_AREAS.map((a) => ({ id: a.id, tabs: a.tabs.slice(), defaultTab: a.defaultTab || null }))));
    } catch (e) { /* ignore */ }
}

function resetMenuAreas() {
    try { localStorage.removeItem(MENU_AREAS_STORAGE_KEY); } catch (e) { /* ignore */ }
    // The menu row goes back to its built-in order too.
    MENU_ORDER.esc = MENU_ORDER_DEFAULT_ESC.slice();
    if (typeof saveMenuOrder === 'function') saveMenuOrder();
    MENU_AREAS.length = 0;
    MENU_AREAS_DEFAULTS.forEach((a) => MENU_AREAS.push(Object.assign({}, a, { tabs: a.tabs.slice() })));
}

(function loadSavedMenuAreas() {
    try {
        const saved = JSON.parse(localStorage.getItem(MENU_AREAS_STORAGE_KEY) || 'null');
        if (saved) applyMenuAreasLayout(saved);
    } catch (e) { /* ignore */ }
})();

// ---- Player-chosen tab / area icons (Menu → LAYOUT, click an icon) ------
// Keys: a tab id ('shop', 'settings', …) or 'area:<id>' for an area button.
var MENU_ICONS_STORAGE_KEY = 'vf.menuIcons';
var MENU_ICONS = {};
try { MENU_ICONS = JSON.parse(localStorage.getItem(MENU_ICONS_STORAGE_KEY) || '{}') || {}; } catch (e) { MENU_ICONS = {}; }

function getMenuIcon(key, fallback) {
    return MENU_ICONS[key] || fallback;
}

function setMenuIcon(key, icon) {
    if (icon) MENU_ICONS[key] = icon;
    else delete MENU_ICONS[key];
    try { localStorage.setItem(MENU_ICONS_STORAGE_KEY, JSON.stringify(MENU_ICONS)); } catch (e) { /* ignore */ }
}

function resetMenuIcons() {
    MENU_ICONS = {};
    try { localStorage.removeItem(MENU_ICONS_STORAGE_KEY); } catch (e) { /* ignore */ }
}

// ---- Player-chosen tab / area names (Menu → LAYOUT, pencil next to a name)
// Same keys as the icons: a tab id or 'area:<id>'.
var MENU_LABELS_STORAGE_KEY = 'vf.menuLabels';
var MENU_LABELS = {};
try { MENU_LABELS = JSON.parse(localStorage.getItem(MENU_LABELS_STORAGE_KEY) || '{}') || {}; } catch (e) { MENU_LABELS = {}; }

function getMenuLabel(key, fallback) {
    return MENU_LABELS[key] || fallback;
}

function setMenuLabel(key, label) {
    if (label) MENU_LABELS[key] = label;
    else delete MENU_LABELS[key];
    try { localStorage.setItem(MENU_LABELS_STORAGE_KEY, JSON.stringify(MENU_LABELS)); } catch (e) { /* ignore */ }
}

function resetMenuLabels() {
    MENU_LABELS = {};
    try { localStorage.removeItem(MENU_LABELS_STORAGE_KEY); } catch (e) { /* ignore */ }
}


/* --- js/graphics/galaxy-icon.js?v=1 --- */
"use strict";

// Generative galaxy icon: a 64x64 pixel disc drawn from the galaxy's real data, so every galaxy looks different.
//   spiral arms   — count / twist seeded by the galaxy id, tinted by the ruling faction
//   planet pixels — the galaxy's real map nodes + links, each in its planet's faction colour (home planet larger)
//   rim           — split into arcs by faction share (full ring when held)
var galaxyIcon = {
    _cache: {},
    SIZE: 64,

    hash(str) {
        let h = 2166136261;
        for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    },

    rng(seed) {
        let a = seed >>> 0;
        return function () {
            a = (a + 0x6D2B79F5) >>> 0;
            let t = a;
            t = Math.imul(t ^ (t >>> 15), t | 1);
            t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    },

    factionColor(fid) {
        const st = typeof factionShipStyles !== 'undefined' && factionShipStyles.getFactionStyle ? factionShipStyles.getFactionStyle(fid) : null;
        return (st && (st.accent || st.hull)) || '#7ec8ff';
    },

    /** PNG data URL for a galaxy id (cached per id + content signature). */
    dataUrl(gid) {
        const pcm = typeof planetConfigManager !== 'undefined' ? planetConfigManager : null;
        if (!pcm || typeof document === 'undefined') return '';
        const map = (pcm.getGalaxyMap && pcm.getGalaxyMap(gid)) || {};
        const nodes = map.nodes || [];
        const ctl = pcm.getGalaxyControl ? pcm.getGalaxyControl(gid) : { main: 'pirate', factions: [{ id: 'pirate', share: 1 }] };
        const sig = gid + '|' + nodes.map((n) => n.planetId).join(',') + '|' + ctl.factions.map((f) => f.id + f.share).join(',');
        if (this._cache[sig]) return this._cache[sig];

        const S = this.SIZE;
        const c = document.createElement('canvas');
        c.width = S; c.height = S;
        const g = c.getContext('2d');
        const R = this.rng(this.hash('galaxy-icon|' + gid));
        const mid = S / 2;
        const px = (x, y, col) => { g.fillStyle = col; g.fillRect(Math.round(x), Math.round(y), 1, 1); };
        const main = this.factionColor(ctl.main);

        // disc
        g.fillStyle = '#070a12';
        for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
            if (Math.hypot(x + 0.5 - mid, y + 0.5 - mid) <= 29.5) g.fillRect(x, y, 1, 1);
        }
        // spiral arms
        const arms = 2 + Math.floor(R() * 3);
        const twist = 1.4 + R() * 2.2;
        const tilt = R() * Math.PI * 2;
        const dense = Math.min(1, 0.45 + nodes.length / 14);
        g.globalAlpha = 0.55;
        for (let a = 0; a < arms; a++) {
            for (let i = 0; i < 90 * dense + 40; i++) {
                const t = R();
                const r = 3 + t * 26;
                const ang = tilt + (a / arms) * Math.PI * 2 + t * twist * Math.PI + (R() - 0.5) * 0.5;
                px(mid + Math.cos(ang) * r, mid + Math.sin(ang) * r, R() < 0.25 ? '#ffffff' : main);
            }
        }
        g.globalAlpha = 1;
        // core glow
        for (let r = 5; r > 0; r--) {
            g.globalAlpha = 0.12 + (5 - r) * 0.1;
            g.fillStyle = main;
            g.beginPath(); g.arc(mid, mid, r, 0, Math.PI * 2); g.fill();
        }
        g.globalAlpha = 1;

        // map links + planets, in the real layout
        const pos = {};
        nodes.forEach((n) => { pos[n.planetId] = [mid + (n.x - 0.5) * 48, mid + (n.y - 0.5) * 48]; });
        g.globalAlpha = 0.5;
        (map.edges || []).forEach((e) => {
            const a = pos[e[0]]; const b = pos[e[1]];
            if (!a || !b) return;
            const steps = Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]));
            for (let i = 0; i <= steps; i += 2) px(a[0] + (b[0] - a[0]) * i / steps, a[1] + (b[1] - a[1]) * i / steps, '#cfe8ff');
        });
        g.globalAlpha = 1;
        nodes.forEach((n) => {
            const p = pos[n.planetId];
            const home = n.planetId === map.startPlanetId;
            const fid = (pcm.getPlanetFactions && pcm.getPlanetFactions(n.planetId)[0]) || ctl.main;
            const s = home ? 4 : 3;
            const x = Math.round(p[0] - s / 2); const y = Math.round(p[1] - s / 2);
            g.fillStyle = '#05060a';
            g.fillRect(x - 1, y - 1, s + 2, s + 2);
            g.fillStyle = this.factionColor(fid);
            g.fillRect(x, y, s, s);
            if (home) { g.fillStyle = '#ffffff'; g.fillRect(x + 1, y + 1, 2, 2); }
        });

        // rim split by faction share
        let from = -Math.PI / 2;
        ctl.factions.forEach((f) => {
            const to = from + f.share * Math.PI * 2;
            g.strokeStyle = this.factionColor(f.id);
            g.lineWidth = 2;
            g.beginPath(); g.arc(mid, mid, 30.5, from, to - (ctl.factions.length > 1 ? 0.06 : 0)); g.stroke();
            from = to;
        });
        return (this._cache[sig] = c.toDataURL());
    },

    html(gid, size) {
        const url = this.dataUrl(gid);
        const px = size || 64;
        return url ? `<img class="hs-galaxy-icon" src="${url}" width="${px}" height="${px}" alt="" style="image-rendering:pixelated">` : '';
    }
};


