/* --- js/core/gamepad/combat.js --- */
"use strict";

// GamepadManager combat mapping: writes into the same inputHandler.keys map
// the keyboard sets (js/core/input-handler/core.js), so playerManager /
// bulletManager need zero changes.
// Shoulders: LB=a, RB=s, LT=d, RT=space (face A also space for fire-to-start).
// Face X/Y/B still alias a/s/d. L3=boost (Shift), R3=switch shot, Start=pause.
// K/S debug cheats are intentionally never mapped to a gamepad.
extendClass(GamepadManager, {
    updateCombat(gamepad) {
        const g = window.game;
        const inputHandler = g && g.inputHandler;
        if (!inputHandler) return;
        this._combatState.any = true;

        const dir = this.direction(gamepad);
        inputHandler.keys['ArrowUp'] = dir.up;
        inputHandler.keys['ArrowDown'] = dir.down;
        inputHandler.keys['ArrowLeft'] = dir.left;
        inputHandler.keys['ArrowRight'] = dir.right;

        // RT (front right) + face A → Space
        const spaceHeld = this.isButtonPressed(gamepad, 7) || this.isButtonPressed(gamepad, 0);
        const wasSpaceHeld = !!this._combatState.space;
        inputHandler.keys[' '] = spaceHeld;
        inputHandler.keys['Space'] = spaceHeld;
        if (spaceHeld && !wasSpaceHeld) this.onSpacePress();
        if (!spaceHeld && wasSpaceHeld) this.onSpaceRelease();
        this._combatState.space = spaceHeld;

        // L3 → Charge Drive boost (was RB before shoulders took fire)
        const shiftHeld = this.isButtonPressed(gamepad, 10);
        inputHandler.keys['Shift'] = shiftHeld;
        inputHandler.keys['ShiftLeft'] = shiftHeld;
        inputHandler.keys['ShiftRight'] = shiftHeld;

        // LB / RB (rear) + face X/Y; LT (front left) + face B
        inputHandler.keys['a'] = this.isButtonPressed(gamepad, 4) || this.isButtonPressed(gamepad, 2);
        inputHandler.keys['s'] = this.isButtonPressed(gamepad, 5) || this.isButtonPressed(gamepad, 3);
        inputHandler.keys['d'] = this.isButtonPressed(gamepad, 6) || this.isButtonPressed(gamepad, 1);

        // R3 → switch shot type (was LB)
        const switchHeld = this.isButtonPressed(gamepad, 11);
        if (switchHeld && !this._combatState.switchShot) {
            if (typeof bulletManager !== 'undefined') {
                const newType = bulletManager.switchShotType();
                if (typeof uiManager !== 'undefined') uiManager.updateShotTypeDisplay(newType);
            }
        }
        this._combatState.switchShot = switchHeld;

        const startHeld = this.isButtonPressed(gamepad, 9); // Start
        if (startHeld && !this._combatState.start) inputHandler.togglePause();
        this._combatState.start = startHeld;
    },

    onSpacePress() {
        if (typeof bulletManager === 'undefined' || typeof playerManager === 'undefined') return;
        const mode = bulletManager.getFireMode ? bulletManager.getFireMode() : 'auto';
        if (mode === 'charge' && !bulletManager.isCharging) {
            bulletManager.beginCharge();
        }
    },

    onSpaceRelease() {
        if (typeof bulletManager === 'undefined' || typeof playerManager === 'undefined') return;
        const mode = bulletManager.getFireMode ? bulletManager.getFireMode() : 'auto';
        if (mode === 'charge' && bulletManager.isCharging) {
            bulletManager.releaseChargeShot(playerManager.getPosition());
        }
    }
});


/* --- js/core/gamepad/menu-nav.js --- */
"use strict";

// GamepadManager menu mapping: every screen outside combat (start screen,
// profile selection, galaxy map, home station, pause menu, modals) already
// listens for real ArrowUp/Down/Left/Right, Enter and Escape keydown events
// on document/window. Rather than rebuild per-screen focus logic, this
// dispatches the same synthetic KeyboardEvents those listeners already
// handle, so D-pad/stick = arrows, A = Enter, B = Escape everywhere a
// keyboard equivalent exists.
//
// One dispatch per press, no auto-repeat: the stick/d-pad must be released
// and pressed again to move further. Holding a direction down must not
// walk through several menu entries - that read as the menu "skipping"
// entries during testing, so repeat-while-held was removed on purpose.
extendClass(GamepadManager, {
    dispatchKey(type, key) {
        const target = (document.activeElement && document.body.contains(document.activeElement))
            ? document.activeElement
            : document.body;
        const event = new KeyboardEvent(type, {
            key,
            code: key,
            bubbles: true,
            cancelable: true
        });
        target.dispatchEvent(event);
    },

    updateMenuDirection(name, key, pressed) {
        const st = this._menuState[name];
        if (pressed && !st.active) {
            st.active = true;
            // Map stick focus: keep the HTML HUD frame off so markGamepad
            // cannot latch onto a leftover .nav-focused tab/button.
            const mapStick = typeof galaxyMapManager !== 'undefined'
                && galaxyMapManager.isInputActive && galaxyMapManager.isInputActive()
                && (!galaxyMapManager.hasCardFocus || !galaxyMapManager.hasCardFocus());
            if (typeof gamepadCursor !== 'undefined') {
                if (mapStick && gamepadCursor._fadeOut) gamepadCursor._fadeOut();
                else gamepadCursor.markGamepad();
            }
            this.dispatchKey('keydown', key);
        } else if (!pressed && st.active) {
            st.active = false;
            this.dispatchKey('keyup', key);
        }
    },

    updateMenu(gamepad) {
        const dir = this.direction(gamepad);
        this.updateMenuDirection('up', 'ArrowUp', dir.up);
        this.updateMenuDirection('down', 'ArrowDown', dir.down);
        this.updateMenuDirection('left', 'ArrowLeft', dir.left);
        this.updateMenuDirection('right', 'ArrowRight', dir.right);

        const aHeld = this.isButtonPressed(gamepad, 0); // A -> Enter
        if (aHeld && !this._menuState.a) {
            if (typeof gamepadCursor !== 'undefined') gamepadCursor.markGamepad();
            this.dispatchKey('keydown', 'Enter');
        }
        if (!aHeld && this._menuState.a) this.dispatchKey('keyup', 'Enter');
        this._menuState.a = aHeld;

        const bHeld = this.isButtonPressed(gamepad, 1) || this.isButtonPressed(gamepad, 8); // B / Back -> Escape
        if (bHeld && !this._menuState.b) {
            if (typeof gamepadCursor !== 'undefined') gamepadCursor.markGamepad();
            this.dispatchKey('keydown', 'Escape');
        }
        if (!bHeld && this._menuState.b) this.dispatchKey('keyup', 'Escape');
        this._menuState.b = bHeld;
    }
});



/* --- js/graphics/shopkeeper-face.js --- */
"use strict";

/**
 * Tiny procedural face for the in-stage shopkeeper: idle / happy (after a
 * purchase) / sad (can't afford). No sprite sheet, just pixel rects on a canvas.
 */
var ShopkeeperFace = class ShopkeeperFace {
    constructor() {
        this.state = 'idle';
        this.timer = 0;
    }

    setState(state, ms) {
        this.state = state;
        this.timer = Math.max(0, Number(ms) || 0);
    }

    update(deltaTime) {
        if (this.timer > 0) {
            this.timer -= deltaTime;
            if (this.timer <= 0) this.state = 'idle';
        }
    }

    /** Draws into a canvas 2D context, filling the whole canvas. */
    render(ctx, w, h) {
        if (!ctx) return;
        const px = Math.max(2, Math.floor(Math.min(w, h) / 16));
        ctx.clearRect(0, 0, w, h);
        ctx.fillStyle = '#e8b878';
        ctx.fillRect(w * 0.2, h * 0.15, w * 0.6, h * 0.7);
        const eyeY = this.state === 'happy' ? h * 0.42 : h * 0.4;
        ctx.fillStyle = '#2a1c10';
        if (this.state === 'happy') {
            // Squinting, happy eyes: short horizontal dashes.
            ctx.fillRect(w * 0.3, eyeY, px * 2, px);
            ctx.fillRect(w * 0.62, eyeY, px * 2, px);
        } else if (this.state === 'sad') {
            ctx.fillRect(w * 0.3, eyeY, px, px * 2);
            ctx.fillRect(w * 0.68, eyeY, px, px * 2);
        } else {
            ctx.fillRect(w * 0.3, eyeY, px, px);
            ctx.fillRect(w * 0.68, eyeY, px, px);
        }
        ctx.fillStyle = '#7a3a28';
        if (this.state === 'happy') {
            ctx.fillRect(w * 0.36, h * 0.62, w * 0.28, px);
            ctx.fillRect(w * 0.34, h * 0.58, px, px);
            ctx.fillRect(w * 0.64, h * 0.58, px, px);
        } else if (this.state === 'sad') {
            ctx.fillRect(w * 0.36, h * 0.68, w * 0.28, px);
            ctx.fillRect(w * 0.34, h * 0.64, px, px);
            ctx.fillRect(w * 0.64, h * 0.64, px, px);
        } else {
            ctx.fillRect(w * 0.38, h * 0.64, w * 0.24, px);
        }
    }
}

var shopkeeperFace = new ShopkeeperFace();
window.shopkeeperFace = shopkeeperFace;


/* --- js/ui/dev-hover-screen.js --- */
"use strict";

/**
 * Dev Mode hover readout: a bezel-bottom screen that names the element under the pointer.
 * Optional highlight mode: with the mode on, hold Shift to tint/outline the target.
 */
(function () {
    const SKIP = /^(vf-hover-screen|vf-hover-k|vf-hover-v|vf-hover-hi|vf-bezel-devmode|vf-hover-hl)$/;
    const HI_KEY = 'vf_dev_hover_hi';
    let screen = null;
    let label = null;
    let hiBtn = null;
    let hl = null;
    let lastKey = '';
    let lastTarget = null;
    let lastX = 0;
    let lastY = 0;
    let raf = 0;
    let shiftDown = false;
    let hiMode = false;
    try { hiMode = localStorage.getItem(HI_KEY) === '1'; } catch (e) { /* ignore */ }

    function ensure() {
        const frame = document.getElementById('vf-bezel');
        if (!frame) return null;
        screen = frame.querySelector('.vf-hover-screen');
        if (!screen) {
            screen = document.createElement('div');
            screen.className = 'vf-hover-screen vf-pilot-screen';
            screen.setAttribute('aria-live', 'polite');
            screen.hidden = true;
            screen.innerHTML = ''
                + '<span class="vf-hover-k">HOVER</span>'
                + '<button type="button" class="vf-hover-hi" title="Highlight mode: hold Shift to tint the element under the pointer" aria-label="Toggle hover highlight mode">HI</button>'
                + '<span class="vf-hover-v">—</span>';
            frame.appendChild(screen);
            screen.querySelector('.vf-hover-hi').addEventListener('click', function (e) {
                e.preventDefault();
                e.stopPropagation();
                setHiMode(!hiMode);
            });
        }
        label = screen.querySelector('.vf-hover-v');
        hiBtn = screen.querySelector('.vf-hover-hi');
        syncHiBtn();
        if (!hl) {
            hl = document.createElement('div');
            hl.className = 'vf-hover-hl';
            hl.hidden = true;
        }
        // Must live on <html>, not <body>: body carries transform: scale(--stage-scale),
        // which makes position:fixed resolve in stage space. Client rects are viewport
        // px — mounting under body made the tint sit offset and look like a ghosted
        // second copy of the station UI (double borders / jumping highlight).
        if (hl.parentElement !== document.documentElement) {
            document.documentElement.appendChild(hl);
        }
        return screen;
    }

    function setHiMode(on) {
        hiMode = !!on;
        try { localStorage.setItem(HI_KEY, hiMode ? '1' : '0'); } catch (e) { /* ignore */ }
        syncHiBtn();
        paint();
    }

    function syncHiBtn() {
        if (!hiBtn) return;
        hiBtn.classList.toggle('is-on', hiMode);
        hiBtn.setAttribute('aria-pressed', hiMode ? 'true' : 'false');
        hiBtn.title = hiMode
            ? 'Highlight ON — hold Shift to tint the hovered element (click to turn off)'
            : 'Highlight OFF — click to enable; then hold Shift to tint';
    }

    function devOn() {
        return typeof startScreenManager !== 'undefined' && !!startScreenManager.devMode;
    }

    function attrToken(el, name) {
        const v = el.getAttribute(name);
        return v != null && v !== '' ? '[' + name + '="' + v + '"]' : '';
    }

    function nodeToken(el) {
        let s = (el.tagName || '?').toLowerCase();
        if (el.id) s += '#' + el.id;
        if (el.classList && el.classList.length) {
            const cls = [];
            for (let i = 0; i < el.classList.length && cls.length < 3; i++) {
                const c = el.classList[i];
                if (SKIP.test(c) || c.indexOf('is-') === 0 || c === 'on') continue;
                cls.push(c);
            }
            if (cls.length) s += '.' + cls.join('.');
        }
        s += attrToken(el, 'data-tool')
            || attrToken(el, 'data-tab')
            || attrToken(el, 'data-area')
            || attrToken(el, 'data-slot')
            || attrToken(el, 'data-slot-kind')
            || attrToken(el, 'role');
        return s;
    }

    function pickTarget(raw) {
        let el = raw;
        while (el && el.nodeType === 1) {
            if (el === screen || el === hl || (el.classList && (
                el.classList.contains('vf-hover-screen')
                || el.classList.contains('vf-hover-hl')
                || el.classList.contains('vf-bezel-devmode')
            ))) {
                el = el.parentElement;
                continue;
            }
            break;
        }
        if (!el || el === document.documentElement || el === document.body) return null;
        let best = el;
        let n = el;
        for (let d = 0; n && n.nodeType === 1 && d < 6; d++) {
            if (n.id
                || n.getAttribute('data-tool')
                || n.getAttribute('data-tab')
                || n.getAttribute('data-area')
                || n.getAttribute('data-slot')
                || n.getAttribute('data-ui-tip')
                || n.getAttribute('aria-label')
                || n.getAttribute('title')
                || n.tagName === 'BUTTON'
                || n.tagName === 'A'
                || n.tagName === 'CANVAS'
                || (n.classList && (
                    n.classList.contains('vf-pilot-screen')
                    || n.classList.contains('vf-bezel-tools')
                    || n.classList.contains('hs-nav-card')
                ))) {
                best = n;
                break;
            }
            if (n.id || (n.classList && n.classList.length > 0)) best = n;
            n = n.parentElement;
        }
        return best;
    }

    function describe(el) {
        const parts = [];
        let n = el;
        for (let d = 0; n && n.nodeType === 1 && d < 4 && n !== document.body; d++) {
            parts.unshift(nodeToken(n));
            if (n.id) break;
            n = n.parentElement;
        }
        let text = parts.join(' › ');
        const tip = el.getAttribute('aria-label')
            || el.getAttribute('title')
            || el.getAttribute('data-ui-tip')
            || '';
        if (tip) text += ' · ' + tip;
        const w = Math.round(el.getBoundingClientRect().width);
        const h = Math.round(el.getBoundingClientRect().height);
        if (w || h) text += ' · ' + w + '×' + h;
        return text;
    }

    function placeHighlight(el) {
        if (!hl) return;
        const show = !!(devOn() && hiMode && shiftDown && el && el.isConnected);
        if (!show) {
            hl.hidden = true;
            lastTarget = null;
            return;
        }
        // hl is on <html> (viewport fixed). Rects are already visual/client px.
        const r = el.getBoundingClientRect();
        if (r.width <= 0 && r.height <= 0) {
            hl.hidden = true;
            lastTarget = null;
            return;
        }
        hl.hidden = false;
        hl.style.left = Math.round(r.left) + 'px';
        hl.style.top = Math.round(r.top) + 'px';
        hl.style.width = Math.max(0, Math.round(r.width)) + 'px';
        hl.style.height = Math.max(0, Math.round(r.height)) + 'px';
        lastTarget = el;
    }

    function paint() {
        raf = 0;
        if (!ensure()) return;
        const on = devOn();
        screen.hidden = !on;
        if (!on) {
            if (lastKey !== '') {
                lastKey = '';
                if (label) label.textContent = '—';
            }
            placeHighlight(null);
            return;
        }
        const prev = screen.style.visibility;
        const hlPrev = hl ? hl.style.visibility : '';
        screen.style.visibility = 'hidden';
        if (hl) hl.style.visibility = 'hidden';
        const raw = document.elementFromPoint(lastX, lastY);
        screen.style.visibility = prev;
        if (hl) hl.style.visibility = hlPrev;
        const el = pickTarget(raw);
        const key = el ? describe(el) : '—';
        if (key !== lastKey) {
            lastKey = key;
            if (label) label.textContent = key;
        }
        placeHighlight(el);
    }

    function schedule(x, y) {
        lastX = x;
        lastY = y;
        if (raf) return;
        raf = requestAnimationFrame(paint);
    }

    document.addEventListener('pointermove', function (e) {
        shiftDown = !!e.shiftKey;
        schedule(e.clientX, e.clientY);
    }, { passive: true, capture: true });

    document.addEventListener('keydown', function (e) {
        if (e.key !== 'Shift') return;
        shiftDown = true;
        if (hiMode && devOn()) paint();
    }, true);

    document.addEventListener('keyup', function (e) {
        if (e.key !== 'Shift') return;
        shiftDown = false;
        placeHighlight(null);
    }, true);

    window.addEventListener('blur', function () {
        shiftDown = false;
        placeHighlight(null);
    });

    // DevMode can flip without a pointer move (Shift+C); keep visibility in sync.
    setInterval(function () {
        if (!ensure()) return;
        const on = devOn();
        if (screen.hidden === on) {
            screen.hidden = !on;
            if (on) paint();
            else {
                if (label) { lastKey = ''; label.textContent = '—'; }
                placeHighlight(null);
            }
        }
        // Keep overlay glued if the target moves/resizes while Shift is held.
        if (on && hiMode && shiftDown && lastTarget) placeHighlight(lastTarget);
    }, 400);

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', ensure);
    } else {
        ensure();
    }
})();


/* --- js/core/profile-manager/item-upgrades.js --- */
"use strict";

// ProfileManager methods, split from profile-manager.js.
// Per-item upgrades (EQUIPMENT tab): one specific weapon/defense/ability/
// energy item id, independent of the category-wide MODULES levels
// (moduleUpgrades). Each item holds several independently leveled stat
// tracks (economyConfig.itemUpgradeTrackDefs), a free-to-switch fire mode
// (weapons only, economyConfig.itemFireModes, unlocked by a track level),
// and a free numeric fine-tune slider (0..1) biasing two of its stats.
extendClass(ProfileManager, {
    ITEM_UPGRADE_BUCKETS: ['weapons', 'defenses', 'abilities', 'energy'],

    /** Split `defId` / `defId#unit` so each owned copy can keep its own upgrades. */
    parsePartInstanceId(itemId) {
        const raw = String(itemId || '');
        const m = raw.match(/^(.*)#(\d+)$/);
        if (m) {
            return {
                defId: m[1],
                unit: Math.max(0, parseInt(m[2], 10) || 0),
                instanceId: raw
            };
        }
        return { defId: raw, unit: null, instanceId: raw };
    },

    partDefId(itemId) {
        return this.parsePartInstanceId(itemId).defId;
    },

    /** Canonical upgrade bag key for one owned copy (`defId#unit`). Bare defId → #0. */
    partInstanceKey(itemId) {
        const p = this.parsePartInstanceId(itemId);
        if (!p.defId) return '';
        const unit = p.unit != null ? p.unit : 0;
        return p.defId + '#' + unit;
    },

    /**
     * Stable unit indices 0..owned-1 packed by location: each ship's equipped copies,
     * then that ship's filed copies (ownedShipIds order), then station leftovers.
     */
    getPartInstanceLayout(profile, bucket, defId) {
        const p = profile || this.getActiveProfile();
        const id = String(defId || '');
        const out = { station: [], ships: {}, owned: 0 };
        if (!p || !id || bucket === 'blueprints') return out;
        let owned = Math.max(0, Math.round(Number(this._ownedStorageCount(p, bucket, id)) || 0));
        if (owned <= 0) {
            // Starter loadout parts can be visible with owned=0 (filed/equipped only).
            const ships = p.ownedShipIds || [];
            let visible = 0;
            ships.forEach((shipId) => {
                visible += this._equippedStorageCount(p, shipId, bucket, id);
                const entry = (p.shipStorage || {})[shipId];
                visible += (entry && entry[bucket] && entry[bucket][id]) || 0;
            });
            owned = Math.max(0, visible);
        }
        out.owned = owned;
        let cursor = 0;
        const take = (n) => {
            const slice = [];
            const count = Math.max(0, Math.round(Number(n) || 0));
            for (let i = 0; i < count && cursor < owned; i++) slice.push(cursor++);
            return slice;
        };
        (p.ownedShipIds || []).forEach((shipId) => {
            const eq = this._equippedStorageCount(p, shipId, bucket, id);
            const entry = (p.shipStorage || {})[shipId];
            const filed = (entry && entry[bucket] && entry[bucket][id]) || 0;
            out.ships[shipId] = take(eq).concat(take(filed));
        });
        while (cursor < owned) out.station.push(cursor++);
        return out;
    },

    /** Upgrade-bag key for the Nth equipped copy of defId on a ship (0-based). */
    getEquippedInstanceId(profile, shipId, bucket, defId, occurrence) {
        const id = String(defId || '');
        const occ = Math.max(0, Math.round(Number(occurrence) || 0));
        const layout = this.getPartInstanceLayout(profile, bucket, id);
        const shipUnits = (layout.ships && layout.ships[shipId]) || [];
        const eq = this._equippedStorageCount(profile, shipId, bucket, id);
        if (occ >= eq || occ >= shipUnits.length) return this.partInstanceKey(id);
        return id + '#' + shipUnits[occ];
    },

    /**
     * After a station↔ship move of one specific unit, slide upgrade bags so the
     * dragged copy keeps its levels under the new packed index.
     */
    remapPartInstanceUpgrades(profile, bucket, defId, fromUnit, toIndex) {
        const p = profile || this.getActiveProfile();
        if (!p || !defId || bucket === 'blueprints') return;
        this.ensureEconomyDefaults(p);
        const bag = p.itemUpgrades && p.itemUpgrades[bucket];
        if (!bag) return;
        const owned = Math.max(0, Math.round(Number(this._ownedStorageCount(p, bucket, defId)) || 0));
        if (owned <= 1) return;
        const from = Math.max(0, Math.round(Number(fromUnit) || 0));
        const to = Math.max(0, Math.round(Number(toIndex) || 0));
        if (from === to || from >= owned || to >= owned) return;
        const arr = [];
        for (let i = 0; i < owned; i++) {
            const k = defId + '#' + i;
            if (bag[k] && typeof bag[k] === 'object') arr.push(bag[k]);
            else if (i === 0 && bag[defId] && typeof bag[defId] === 'object') arr.push(bag[defId]);
            else arr.push(null);
        }
        const moved = arr.splice(from, 1)[0];
        arr.splice(to, 0, moved);
        if (bag[defId]) delete bag[defId];
        for (let i = 0; i < owned; i++) {
            const k = defId + '#' + i;
            if (arr[i]) bag[k] = arr[i];
            else delete bag[k];
        }
    },

    /** Raw per-item entry ({ tracks, mode, tune }), ensuring buckets exist first. */
    _itemUpgradeEntry(bucket, itemId, profile) {
        const p = profile || this.getActiveProfile();
        if (!p) return null;
        this.ensureEconomyDefaults(p);
        const b = String(bucket || '');
        const parsed = this.parsePartInstanceId(itemId);
        if (!parsed.defId) return null;
        const id = this.partInstanceKey(parsed.instanceId);
        const bag = p.itemUpgrades && p.itemUpgrades[b];
        if (!bag) return null;
        // Legacy saves keyed upgrades by bare defId — fold onto #0 once.
        if (!bag[id] && bag[parsed.defId] && typeof bag[parsed.defId] === 'object') {
            bag[id] = bag[parsed.defId];
            delete bag[parsed.defId];
        }
        if (!bag[id] || typeof bag[id] !== 'object') {
            bag[id] = { tracks: {}, mode: 'single', tune: 0.5, tuneUnlocked: false };
        }
        return bag[id];
    },

    getItemTrackLevel(bucket, itemId, track, profile) {
        const entry = this._itemUpgradeEntry(bucket, itemId, profile);
        if (!entry) return 0;
        return Math.max(0, Math.round(Number(entry.tracks[track]) || 0));
    },

    /** Combined level across all tracks — used where a single display number is wanted. */
    getItemUpgradeLevel(bucket, itemId, profile) {
        const entry = this._itemUpgradeEntry(bucket, itemId, profile);
        if (!entry) return 0;
        return Object.keys(entry.tracks).reduce((sum, t) => sum + Math.max(0, Math.round(Number(entry.tracks[t]) || 0)), 0);
    },

    /** Owned anywhere (station/ship storage) or currently equipped on any owned ship.
     *  Instance ids (`defId#unit`) resolve against the bare defId ledger. */
    _itemIsOwnedOrEquipped(profile, bucket, itemId) {
        const parsed = this.parsePartInstanceId(itemId);
        const defId = parsed.defId;
        if (!defId) return false;
        const owned = this._ownedStorageCount(profile, bucket, defId);
        if (parsed.unit != null) {
            if (owned > 0) return parsed.unit >= 0 && parsed.unit < owned;
            // owned=0 starter copies still upgradeable while filed/equipped
            const layout = this.getPartInstanceLayout(profile, bucket, defId);
            return parsed.unit >= 0 && parsed.unit < layout.owned;
        }
        if (owned > 0) return true;
        if (this._equippedStorageCountAll(profile, bucket, defId) > 0) return true;
        const map = profile.shipStorage || {};
        return Object.keys(map).some((shipId) => {
            const entry = map[shipId] && map[shipId][bucket];
            return !!(entry && (entry[defId] || 0) > 0);
        });
    },

    canPurchaseItemTrackUpgrade(bucket, itemId, track, profile) {
        const p = profile || this.getActiveProfile();
        if (!p || typeof economyConfig === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        this.ensureEconomyDefaults(p);
        const b = String(bucket || '');
        const id = String(itemId || '');
        const trackDefs = economyConfig.itemUpgradeTrackDefs[b];
        if (this.ITEM_UPGRADE_BUCKETS.indexOf(b) === -1 || !id || !trackDefs || !trackDefs[track]) {
            return { ok: false, reason: 'INVALID' };
        }
        if (economyConfig.itemTrackApplies && !economyConfig.itemTrackApplies(b, id, track)) {
            return { ok: false, reason: 'INVALID' };
        }
        if (!this._itemIsOwnedOrEquipped(p, b, id)) {
            return { ok: false, reason: 'NOT_OWNED' };
        }
        const level = this.getItemTrackLevel(b, id, track, p);
        const max = trackDefs[track].maxLevel || 5;
        if (level >= max) return { ok: false, reason: 'MAX LEVEL' };
        const cost = economyConfig.getItemTrackUpgradeCost(b, id, track, level + 1);
        if (!cost) return { ok: false, reason: 'INVALID' };
        if (!economyConfig.canAfford(p.resources, cost)) {
            return { ok: false, reason: 'RESOURCES', cost: cost, nextLevel: level + 1 };
        }
        return { ok: true, cost: cost, nextLevel: level + 1 };
    },

    purchaseItemTrackUpgrade(bucket, itemId, track) {
        const profile = this.getActiveProfile();
        if (!profile || typeof economyConfig === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        this.ensureEconomyDefaults(profile);
        const check = this.canPurchaseItemTrackUpgrade(bucket, itemId, track, profile);
        if (!check.ok) return check;
        if (!this.spendResources(check.cost)) {
            return { ok: false, reason: 'RESOURCES' };
        }
        const entry = this._itemUpgradeEntry(bucket, itemId, profile);
        entry.tracks[track] = check.nextLevel;
        this.save();
        return { ok: true, level: check.nextLevel };
    },

    /** Fire modes unlocked so far for this item (weapons only; other buckets have none yet). */
    getAvailableItemModes(bucket, itemId, profile) {
        if (bucket !== 'weapons' || typeof economyConfig === 'undefined' || !economyConfig.itemFireModes) return [];
        return Object.keys(economyConfig.itemFireModes).filter((modeId) => {
            const def = economyConfig.itemFireModes[modeId];
            if (!def.unlockTrack) return true;
            return this.getItemTrackLevel(bucket, itemId, def.unlockTrack, profile) >= (def.unlockLevel || 1);
        });
    },

    getItemMode(bucket, itemId, profile) {
        const entry = this._itemUpgradeEntry(bucket, itemId, profile);
        return (entry && entry.mode) || 'single';
    },

    /** Free to switch once unlocked — no resource cost. */
    setItemMode(bucket, itemId, mode) {
        const profile = this.getActiveProfile();
        const entry = this._itemUpgradeEntry(bucket, itemId, profile);
        if (!entry) return { ok: false, reason: 'NO PROFILE' };
        if (this.getAvailableItemModes(bucket, itemId, profile).indexOf(mode) === -1) {
            return { ok: false, reason: 'LOCKED' };
        }
        entry.mode = mode;
        this.save();
        return { ok: true, mode: mode };
    },

    /** Fine-tune unlocked via one-time purchase on that item. */
    isItemTuneUnlocked(bucket, itemId, profile) {
        const entry = this._itemUpgradeEntry(bucket, itemId, profile);
        return !!(entry && entry.tuneUnlocked);
    },

    canPurchaseItemTuneUnlock(bucket, itemId, profile) {
        const p = profile || this.getActiveProfile();
        if (!p || typeof economyConfig === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        this.ensureEconomyDefaults(p);
        const b = String(bucket || '');
        const id = String(itemId || '');
        if (this.ITEM_UPGRADE_BUCKETS.indexOf(b) === -1 || !id || !economyConfig.itemTuneUnlock[b]) {
            return { ok: false, reason: 'INVALID' };
        }
        if (!this._itemIsOwnedOrEquipped(p, b, id)) {
            return { ok: false, reason: 'NOT_OWNED' };
        }
        if (this.isItemTuneUnlocked(b, id, p)) {
            return { ok: false, reason: 'OWNED' };
        }
        const cost = economyConfig.getItemTuneUnlockCost(b);
        if (!cost) return { ok: false, reason: 'INVALID' };
        if (!economyConfig.canAfford(p.resources, cost)) {
            return { ok: false, reason: 'RESOURCES', cost: cost };
        }
        return { ok: true, cost: cost };
    },

    purchaseItemTuneUnlock(bucket, itemId) {
        const profile = this.getActiveProfile();
        if (!profile || typeof economyConfig === 'undefined') {
            return { ok: false, reason: 'NO PROFILE' };
        }
        this.ensureEconomyDefaults(profile);
        const check = this.canPurchaseItemTuneUnlock(bucket, itemId, profile);
        if (!check.ok) return check;
        if (!this.spendResources(check.cost)) {
            return { ok: false, reason: 'RESOURCES' };
        }
        const entry = this._itemUpgradeEntry(bucket, itemId, profile);
        entry.tuneUnlocked = true;
        this.save();
        return { ok: true };
    },

    getItemTune(bucket, itemId, profile) {
        if (!this.isItemTuneUnlocked(bucket, itemId, profile)) return 0.5;
        const entry = this._itemUpgradeEntry(bucket, itemId, profile);
        return entry ? Math.max(0, Math.min(1, Number(entry.tune))) : 0.5;
    },

    /** Free fine-tune slider (0..1) once unlocked — biases two of the item's stats against each other. */
    setItemTune(bucket, itemId, value) {
        const profile = this.getActiveProfile();
        const entry = this._itemUpgradeEntry(bucket, itemId, profile);
        if (!entry) return { ok: false, reason: 'NO PROFILE' };
        if (!this.isItemTuneUnlocked(bucket, itemId, profile)) {
            return { ok: false, reason: 'LOCKED' };
        }
        entry.tune = Math.max(0, Math.min(1, Number(value)));
        this.save();
        return { ok: true, tune: entry.tune };
    },

    /** Same progressive ramp as getModuleUpgradeBonuses, scoped to one item's own track levels. */
    getItemUpgradeBonuses(bucket, itemId, profile) {
        const p = profile || this.getActiveProfile();
        const ramp = (lv, base, accel) => {
            const n = Math.max(0, Math.round(Number(lv) || 0));
            if (n <= 0) return 0;
            let total = 0;
            for (let i = 1; i <= n; i++) total += base + (i - 1) * accel;
            return total;
        };
        const trackLevel = (track) => p ? this.getItemTrackLevel(bucket, itemId, track, p) : 0;
        if (bucket === 'weapons') {
            return {
                damageMul: 1 + ramp(trackLevel('dmg'), 0.05, 0.02),
                cooldownMul: Math.max(0.6, 1 - ramp(trackLevel('rof'), 0.04, 0.015)),
                rangeMul: 1 + ramp(trackLevel('range'), 0.04, 0.015),
                reflectiveShots: trackLevel('reflect') > 0,
                chainSlow: trackLevel('chain') > 0
                    && (typeof economyConfig === 'undefined' || !economyConfig.itemTrackApplies
                        || economyConfig.itemTrackApplies('weapons', itemId, 'chain'))
            };
        }
        if (bucket === 'defenses') {
            return {
                capacityMul: 1 + ramp(trackLevel('capacity'), 0.055, 0.025),
                harden: Math.min(0.25, ramp(trackLevel('harden'), 0.025, 0.01)),
                regenMul: 1 + ramp(trackLevel('regen'), 0.07, 0.03)
            };
        }
        // abilities / energy
        return {
            cooldownMul: Math.max(0.6, 1 - ramp(trackLevel('cooldown'), 0.04, 0.015)),
            potencyMul: 1 + ramp(trackLevel('potency'), 0.06, 0.025),
            durationMul: 1 + ramp(trackLevel('duration'), 0.055, 0.02)
        };
    },
});


/* --- js/core/gamepad/cursor.js --- */
"use strict";

/**
 * Animated gamepad menu cursor: a HUD frame that jumps between focused buttons
 * when the controller drives navigation. Mouse/pen input hides it again.
 */
(function () {
    const PAD = 6;
    /** Class cleanup only — visual hide is instant via removing is-on. */
    const HIDE_MS = 0;
    const LERP = 0.28;
    const SNAP = 0.6;

    function GamepadCursor() {
        this.el = null;
        this.active = false;
        this.target = null;
        this.raf = 0;
        this.hideTimer = 0;
        this.x = 0;
        this.y = 0;
        this.w = 0;
        this.h = 0;
        this.hasPos = false;
        this.reduceMotion = false;
        try {
            this.reduceMotion = !!(window.matchMedia
                && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
        } catch (e) { /* ignore */ }
        this._bindInput();
    }

    GamepadCursor.prototype._bindInput = function () {
        const self = this;
        document.addEventListener('pointerdown', function (e) {
            if (e.pointerType === 'mouse' || e.pointerType === 'pen') self.markPointer();
        }, true);
        document.addEventListener('mousemove', function (e) {
            // Only real mouse deltas dismiss the cursor (ignore synthetic 0,0).
            if (e.movementX || e.movementY) self.markPointer();
        }, { passive: true, capture: true });
    };

    GamepadCursor.prototype.ensure = function () {
        // Mount on <html>, not <body>: body carries transform: scale(--stage-scale),
        // so position:fixed resolves in stage space while getBoundingClientRect is
        // viewport px (same trap as js/ui/dev-hover-screen.js).
        const root = document.documentElement;
        if (this.el && root.contains(this.el) && this.el.parentElement === root) return this.el;
        const el = this.el || document.createElement('div');
        el.className = 'vf-gp-cursor';
        el.setAttribute('aria-hidden', 'true');
        if (!el.childElementCount) el.innerHTML = '<i></i><i></i><i></i><i></i>';
        if (el.parentElement !== root) root.appendChild(el);
        this.el = el;
        return el;
    };

    GamepadCursor.prototype.markGamepad = function () {
        this.active = true;
        if (this.hideTimer) { clearTimeout(this.hideTimer); this.hideTimer = 0; }
        const el = this.ensure();
        el.classList.remove('is-out');
        const focused = this._resolveTarget();
        if (focused) this.follow(focused);
        // No target yet: stay armed, but do not paint a floating ghost frame.
        this._kick();
    };

    GamepadCursor.prototype.markPointer = function () {
        if (!this.active && !(this.el && this.el.classList.contains('is-on'))) return;
        this.active = false;
        this.target = null;
        this._fadeOut();
    };

    GamepadCursor.prototype.follow = function (el) {
        if (!el || !el.getBoundingClientRect) return;
        if (!this.active) return;
        this.target = el;
        if (this.hideTimer) { clearTimeout(this.hideTimer); this.hideTimer = 0; }
        const node = this.ensure();
        node.classList.remove('is-out');
        node.classList.add('is-on', 'is-jump');
        this._kick();
    };

    GamepadCursor.prototype._fadeOut = function () {
        const el = this.el;
        if (!el) return;
        // Drop is-on immediately so :not(.is-on) rules kill the frame this frame
        // (no opacity linger — previous HIDE_MS/CSS fade felt a beat too late).
        el.classList.remove('is-jump', 'is-on');
        el.classList.add('is-out');
        el.style.width = '0px';
        el.style.height = '0px';
        this.hasPos = false;
        this.target = null;
        const self = this;
        if (this.hideTimer) clearTimeout(this.hideTimer);
        this.hideTimer = setTimeout(function () {
            self.hideTimer = 0;
            if (self.active) return;
            el.classList.remove('is-on', 'is-out');
        }, HIDE_MS);
    };

    GamepadCursor.prototype._kick = function () {
        if (this.raf) return;
        const self = this;
        this.raf = requestAnimationFrame(function tick() {
            self.raf = 0;
            if (!self.active) return;
            self._paint();
            self.raf = requestAnimationFrame(tick);
        });
    };

    /** Menu screens that use .selected instead of (or as well as) .nav-focused. */
    GamepadCursor.prototype._selectedFallback = function () {
        return document.querySelector(
            '#victoryOverlay .victory-button.selected, ' +
            '#gameOver .victory-button.selected, ' +
            '#gameOver .game-over-button.selected, ' +
            '#pauseOverlay .pause-button.selected'
        );
    };

    GamepadCursor.prototype._resolveTarget = function () {
        // Galaxy map stick focus uses SVG selection frames, not this HUD frame.
        try {
            if (typeof galaxyMapManager !== 'undefined'
                && galaxyMapManager.isInputActive
                && galaxyMapManager.isInputActive()
                && (!galaxyMapManager.hasCardFocus || !galaxyMapManager.hasCardFocus())) {
                this.target = null;
                return null;
            }
        } catch (e) { /* ignore */ }
        if (this.target && document.body.contains(this.target)
            && (this.target.classList.contains('nav-focused')
                || this.target.classList.contains('selected'))) {
            return this.target;
        }
        const focused = document.querySelector('.nav-focused') || this._selectedFallback();
        if (focused) {
            this.target = focused;
            return focused;
        }
        const ae = document.activeElement;
        if (ae && ae !== document.body && ae.getBoundingClientRect
            && typeof ae.matches === 'function'
            && ae.matches('button, [data-nav-item], [role="button"], a[href], input, select, textarea')) {
            this.target = ae;
            return ae;
        }
        return null;
    };

    GamepadCursor.prototype._paint = function () {
        const el = this.ensure();
        if (el.classList.contains('is-out') && !this.active) return;
        const target = this._resolveTarget();
        if (!target) {
            // Target gone (screen swap / rebuild): clear the frame now, but stay
            // armed — markGamepad may run before the key handler sets nav-focused.
            if (this.hasPos || el.classList.contains('is-on')) {
                el.classList.remove('is-jump', 'is-on');
                el.classList.add('is-out');
                el.style.width = '0px';
                el.style.height = '0px';
                this.hasPos = false;
                this.target = null;
            }
            return;
        }
        const r = target.getBoundingClientRect();
        if (r.width <= 0 && r.height <= 0) {
            if (this.hasPos || el.classList.contains('is-on')) {
                el.classList.remove('is-jump', 'is-on');
                el.classList.add('is-out');
                el.style.width = '0px';
                el.style.height = '0px';
                this.hasPos = false;
                this.target = null;
            }
            return;
        }
        el.classList.remove('is-out');
        el.classList.add('is-on');
        const tx = r.left - PAD;
        const ty = r.top - PAD;
        const tw = r.width + PAD * 2;
        const th = r.height + PAD * 2;
        if (!this.hasPos || this.reduceMotion) {
            this.x = tx; this.y = ty; this.w = tw; this.h = th;
            this.hasPos = true;
        } else {
            const dx = tx - this.x;
            const dy = ty - this.y;
            const dw = tw - this.w;
            const dh = th - this.h;
            const dist = Math.abs(dx) + Math.abs(dy) + Math.abs(dw) + Math.abs(dh);
            const k = dist > 180 ? Math.min(1, LERP * 1.8) : LERP;
            this.x += dx * k;
            this.y += dy * k;
            this.w += dw * k;
            this.h += dh * k;
            if (dist < SNAP) {
                this.x = tx; this.y = ty; this.w = tw; this.h = th;
                el.classList.remove('is-jump');
            } else {
                el.classList.add('is-jump');
            }
        }
        el.style.transform = 'translate(' + this.x.toFixed(1) + 'px,' + this.y.toFixed(1) + 'px)';
        el.style.width = this.w.toFixed(1) + 'px';
        el.style.height = this.h.toFixed(1) + 'px';
    };

    const gamepadCursor = new GamepadCursor();
    window.gamepadCursor = gamepadCursor;
})();


/* --- js/ui/content-viewer-stat-range.js --- */
"use strict";

/**
 * Shared by the weapon/ability/defense/energy library viewers: every equippable item's stats
 * are not fixed — they scale across the category's MODULES upgrade tracks (economyConfig
 * .moduleUpgradeDefs), so a flat number in the wiki would be wrong the moment the player
 * upgrades anything. This lists each track's own label/description — the real upgrade system,
 * not invented numbers — as "stat rows" so every item's page reads "this varies, upgradeable
 * via these tracks" instead of implying a fixed value.
 */
function contentViewerUpgradeRangeRowsHtml(category) {
    if (typeof economyConfig === 'undefined' || !economyConfig.moduleUpgradeDefs) return '';
    const tracks = economyConfig.moduleUpgradeDefs[category];
    if (!tracks) return '';
    return Object.keys(tracks).map((track) => {
        const meta = tracks[track];
        return `<div class="stat-row"><span class="stat-label">Range: ${meta.label}</span>` +
            `<span class="stat-value">${meta.desc} · L0–L${meta.maxLevel}</span></div>`;
    }).join('');
}

